'use strict';
let activeProject='main';
let editEpoch=0,apiBusy=0,workbookSwitching=false;
let activeWorkbook=globalThis.localStorage?.getItem('cn-workbook')||'legacy',bulkRunning=false,bulkStop=false,bulkResults=[];
let state,record,result,page='Dashboard',step=0,saveTimer,saveQueue=Promise.resolve(),settingDraft,importPending;
const steps=['Select Party','Check Ledger','Assign Payments','Check Benefits','Review & Finish'];
const $=x=>document.querySelector(x), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'₹'+Number(x||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const uid=()=>crypto.randomUUID();const date=x=>x?new Date(x+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}).replaceAll(' ','-'):'Missing original date';
const option=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
async function api(path,data,background=false){const scope=activeWorkbook,projectScope=activeProject;if(!background)apiBusy++;try{let r=await fetch(path,{...(data===undefined?{}:{method:'POST',body:JSON.stringify(data)}),headers:{'Content-Type':'application/json','X-CN-Workbook':scope,'X-CN-Project':projectScope,...(state?.token?{'X-CN-Token':state.token}:{})}});let b=await r.json();if(projectScope!==activeProject)throw Error('Project changed; reopen this action.');if(!r.ok)throw Error(b.error||'Request failed');return b}finally{if(!background)apiBusy--;}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',7000);if($('#modal')?.open){let feedback=$('#dialog-feedback');if(!feedback){feedback=document.createElement('div');feedback.id='dialog-feedback';feedback.className='warn dialog-feedback';feedback.setAttribute('role','alert');$('#dialogbody').prepend(feedback);}feedback.textContent=t;feedback.scrollIntoView?.({block:'nearest'});}}
function modal(html){$('#dialogbody').innerHTML=html;$('#modal').showModal()}
function field(label,key,value,type='text'){return `<label>${esc(label)}<input data-field="${esc(key)}" type="${type}" value="${esc(value)}"></label>`}
function chk(label,key,value){return `<label class="check"><input type="checkbox" data-field="${key}" ${value?'checked':''}>${esc(label)}</label>`}
function blank(){return {workbook_id:activeWorkbook,annual_ledger:activeWorkbook!=='legacy',workbook_scheme_state:activeWorkbook!=='legacy'?state.workbook?.state:undefined,party:'',location:'',state:state.workbook?.state||'',scheme_state:'',override_reason:'',season:state.settings.seasons[0]?.name||'',opening:'0',closing:'0',old_dues:'0',entries:[],allocations:[],cash_splits:[],opening_sources:[],ledger_confirmed:false,status:'draft',revision:0,manual_order:false}}
async function refresh(){try{state=await api('/api/state');}catch(err){if(!state&&activeWorkbook!=='legacy'){activeWorkbook='legacy';globalThis.localStorage?.removeItem('cn-workbook');state=await api('/api/state');}else throw err;}drawNav()}
function navIcon(name){const paths={Dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',Workbooks:'M4 4h16v16H4zM8 4v16M11 8h6M11 12h6',Parties:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75','Ledger Audit':'M9 3H5v18h14V3h-4M9 3v3h6V3zM8 13l3 3 5-6','Year Link':'M9 15l6-6M8 7l2-2a4 4 0 0 1 6 6l-2 2M16 17l-2 2a4 4 0 0 1-6-6l2-2',Reports:'M4 21V3M4 21h17M9 17v-5M14 17V7M19 17V4',Settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',History:'M3 11a9 9 0 1 1 2 7M3 3v8h8M12 7v5l3 2'};return `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.Workbooks}"/></svg>`;}
function drawNav(){const current=['Calculate CN','Bulk Import'].includes(page)?'Parties':page;$('#nav').innerHTML='<div class="nav-brand"><span class="brand-leaf" aria-hidden="true"><svg viewBox="0 0 48 48" width="44" height="44"><path fill="#62df78" d="M43 3C15 5 14 22 22 31 34 36 43 22 43 3Z"/><path fill="none" stroke="#abffc2" stroke-width="2" d="M16 43 35 13"/><path fill="#2caf64" d="M5 18C5 31 9 36 19 36 18 27 13 21 5 18Z"/></svg></span><strong>ALL CROP</strong><small>CN WORKSPACE</small></div>'+projectNav()+workbookNav()+['Dashboard','Workbooks','Parties','Ledger Audit','Year Link','Reports','Settings','History'].map(x=>`<button data-page="${x}" class="${current===x?'active':''}" ${current===x?'aria-current="page"':''}>${navIcon(x)}<span>${x}</span></button>`).join('')+'<div class="nav-foot"><span class="local-dot"></span> Offline workspace<small>Science. Precision. Growth.</small></div>';const label=$('#workspace-context');if(label)label.textContent=(state?.project?.name||'My Work')+' · '+(state?.workbook?.name||'Existing calculations');}
function pageHead(title,description,section='WORKSPACE'){return `<div class="page-masthead"><div><span class="eyebrow">${esc(section)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div><span class="scope-chip">${navIcon('Workbooks')}${esc(state.workbook?.name||'Existing calculations')}</span></div>`;}
function uiMetric(label,value,note,icon='Reports'){return `<div class="ui-metric"><span class="ui-metric-icon">${navIcon(icon)}</span><div><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div></div>`;}
function statusPill(status){return `<span class="status-pill status-${['draft','finalised','issued'].includes(status)?status:'other'}">${esc(status||'Unknown')}</span>`;}
let dashboardSequence=0;
function dashboardPage(){const rows=(state.records||[]).filter(r=>!r.deleted_at),parties=partyList(),drafts=rows.filter(r=>r.status==='draft'),finalised=rows.filter(r=>r.status==='finalised'),issued=rows.filter(r=>r.status==='issued');const latest=[...rows].sort((a,b)=>String(b.saved_at||'').localeCompare(String(a.saved_at||''))).slice(0,7);$('#main').innerHTML=pageHead('Dashboard','Your selected workbook, saved calculations and next actions in one place.','OVERVIEW')+`<section class="dashboard-hero"><div><span class="eyebrow">YOUR CN WORKSPACE</span><h2>From ledger to credit note.</h2><p>Open a party, review its ledger and continue your calculation.</p><div class="actions"><button data-page="Parties" class="primary">Open Parties →</button><button data-action="new">New Calculation</button><button data-page="Workbooks">Manage Workbooks</button></div></div><div class="hero-mark" aria-hidden="true">${navIcon('Reports')}</div></section><div class="ui-metrics">${uiMetric('Parties',parties.length,'In the selected workbook','Parties')}${uiMetric('Draft calculations',drafts.length,'Continue review and allocation','History')}${uiMetric('Finalised',finalised.length,'Completed, awaiting issue','Ledger Audit')}${uiMetric('Issued',issued.length,'Saved issued records','Reports')}</div><div class="dashboard-columns"><section class="card"><div class="section-heading"><div><span class="eyebrow">SAVED ON THIS PC</span><h2>Recent calculations</h2></div><button data-page="History">View all</button></div><div class="tablewrap"><table><thead><tr><th>Party / season</th><th>Status</th><th>Balance</th><th></th></tr></thead><tbody>${latest.map(r=>`<tr><td><strong>${esc(r.party||'Unnamed draft')}</strong><small class="cell-note">${esc(r.location)} · ${esc(r.season)}</small></td><td>${statusPill(r.status)}</td><td>${money(r.result?.final_balance??r.closing)}<small class="cell-note">${r.result?'After proposed CN':'Ledger before new CN'}</small></td><td><button data-open="${esc(r.id)}">Continue →</button></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state"><h3>Your first calculation starts here</h3><p>Create a workbook or open Parties to import your ledger.</p><button data-action="new" class="primary">New Calculation</button></div></td></tr>'}</tbody></table></div></section><section class="card dashboard-next"><span class="eyebrow">WORKBOOK SETUP</span><h2>Ready for the season?</h2><p>Review the selected workbook’s dates, products and saved schemes before finalisation.</p><button data-page="Settings">Review Settings →</button><hr><h3>Review source ledgers</h3><p>Run independent ledger checks or reconcile April–March financial years.</p><div class="actions"><button data-page="Ledger Audit">Ledger Audit</button><button data-page="Year Link">Year Link</button></div><details><summary>Reference examples</summary><p>These are test/reference tools, not live party data.</p><button data-action="fixture">Import Ashapura test PDF</button><button data-action="saini">View Saini approved reference</button></details></section></div>${workbookAttentionShell()}<section class="card dashboard-reports"><div class="section-heading"><div><span class="eyebrow">ALL ACTIVE WORKBOOKS</span><h2>State · HQ · Party intelligence</h2></div><button data-page="Reports">Open Reports →</button></div><div id="dashboard-report"><p class="muted">Loading completed snapshot totals…</p></div></section>`;loadDashboardReport();loadWorkbookAttention();}
async function loadDashboardReport(){const seq=++dashboardSequence,scope=activeWorkbook;try{const data=await api('/api/territory-report',{filters:territoryFilters},true);if(seq!==dashboardSequence||page!=='Dashboard'||scope!==activeWorkbook)return;const el=$('#dashboard-report');if(!el)return;if(data.hierarchy){el.innerHTML=territoryDashboardHTML(data);return;}el.innerHTML=`<p class="muted">Latest completed snapshots across all active workbooks. Full scheme entitlement; individual record balances above are not added together.</p><div class="ui-metrics report-metrics">${uiMetric('Completed product rows',data.summary.products,'After overlap checks')}${uiMetric('Scheme CN entitlement',money(data.summary.total_CN),'Full entitlement, not incremental issue')}${uiMetric('Net realisation',money(data.summary.net_realisation),'Known configured billing only')}</div>${data.notes.map(n=>`<p class="warn">${esc(n)}</p>`).join('')}<p class="muted">NRV = configured billing − scheme-benefit CN per net sold unit. Freight and requested changes are excluded. Open Reports for product/packing-level weighted NRV.</p>`;}catch(err){if(page==='Dashboard'&&seq===dashboardSequence&&scope===activeWorkbook){const el=$('#dashboard-report');if(el)el.innerHTML=`<p class="warn">Reporting overview unavailable: ${esc(err.message)}</p><button data-page="Reports">Open Reports</button>`;}}}

async function calculate(){result=await api('/api/calculate',record)}
function saveDraft(){saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(record?.status!=='draft')return;if(Number(record.opening)>0)record.opening_dues_review_required=true;let epoch=editEpoch, snapshot=structuredClone(record);let saved=await api('/api/save',snapshot);if(epoch===editEpoch)record=saved;else Object.assign(record,{id:saved.id,revision:saved.revision,saved_at:saved.saved_at,status:saved.status,lineage:saved.lineage});$('#saved').textContent='Saved '+new Date(record.saved_at).toLocaleTimeString('en-IN');await refresh();});return saveQueue}
function changed(){editEpoch++;record.ledger_confirmed=false;clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft().catch(e=>toast(e.message)),700)}
async function openRecord(id){mappingCropChoices={};clearTimeout(saveTimer);await saveQueue;if(record?.status==='draft'&&!record.deleted_at&&(record.entries.length||record.party))await saveDraft();record=structuredClone(state.records.find(x=>x.id===id));if(record?.deleted_at)throw Error('Restore this party from Deleted Parties first.');$('#modal').close();page='Calculate CN';step=record.entries?.length||record.source?1:0;await calculate();render()}
function render(){drawNav();if(page==='Dashboard')return dashboardPage();if(page==='Reports')return reportsPage();if(page==='Year Link')return yearLinkPage();if(page==='Ledger Audit')return auditPage();if(page==='Workbooks')return workbooksPage();if(page==='Bulk Import')return bulkPage();if(page==='Settings')return settingsPage();if(page==='Calculate CN')return workspace();if(page==='Parties')return partiesPage();let list=(state.records||[]).filter(r=>!r.deleted_at);$('#main').innerHTML=`${pageHead(page,'Saved calculations in your selected workbook.','RECORD HISTORY')}<p class="muted">Saved records on this PC. Proposed and issued CNs remain separate from the actual ledger.</p><div class="actions"><button class="primary" data-action="new">New Calculation</button><input id="search" placeholder="Search party, season, crop or status" aria-label="Search records"></div>${page==='Dashboard'?`<div class="card"><h2>Continue Draft</h2><p>${list.filter(r=>r.status==='draft').length} saved draft(s). ${list.filter(r=>r.status==='finalised').length} finalised calculation(s).</p><button data-action="fixture">Import Ashapura test PDF</button><button data-action="saini">View Saini approved reference</button></div><div class="warn">Confirm the selected workbook’s season, state and scheme settings before finalisation.</div>`:''}<div class="card tablewrap"><table><thead><tr><th>Party / location</th><th>Season</th><th>Status / version</th><th>Balance</th><th>Saved</th><th></th></tr></thead><tbody id="records">${recordRows(list)}</tbody></table></div>`;$('#search').oninput=e=>$('#records').innerHTML=recordRows(list.filter(r=>JSON.stringify([r.party,r.season,r.status,r.result?.groups]).toLowerCase().includes(e.target.value.toLowerCase())))}
function recordRows(list){if(!list.length)return '<tr><td colspan="6"><div class="empty-state"><h3>No saved calculations here yet</h3><p>Open Parties or create a new calculation to begin.</p></div></td></tr>';return list.map(r=>`<tr><td>${esc(r.party||'Unnamed draft')}<br>${esc(r.location)}</td><td>${esc(r.season)}</td><td>${statusPill(r.status)} · saved revision ${r.revision}</td><td>${money(r.result?.final_balance??r.closing)}<br><small>${r.result?'After proposed CN':'Ledger before new CN'}</small></td><td>${esc(new Date(r.saved_at).toLocaleString('en-IN'))}</td><td><button data-open="${r.id}">Open / Continue</button>${r.parent?`<button data-compare="${r.id}">Compare versions</button>`:''}</td></tr>`).join('')}
let showDeletedParties=false,partyRemovalPending=null;
function partyKey(r){return r.party?.trim()?JSON.stringify([r.party.trim().toLocaleLowerCase(),(r.location||'').trim().toLocaleLowerCase()]):r.id;}
function partyList(deleted=false){const groups=new Map();for(const r of state.records||[]){if(Boolean(r.deleted_at)!==deleted)continue;const key=partyKey(r);if(!groups.has(key))groups.set(key,{...r,calculations:[]});groups.get(key).calculations.push(r);}return [...groups.values()].map(g=>{const preferred=g.calculations.find(r=>r.entries?.length)||g.calculations.find(r=>r.source)||g.calculations[0];return {...preferred,calculations:g.calculations};}).sort((a,b)=>(a.party||'').localeCompare(b.party||''));}
function partyRows(parties,deleted=showDeletedParties){if(!parties.length)return '<tr><td colspan="3"><div class="empty-state"><h3>No matching parties</h3><p>Change your search or import a ledger to get started.</p></div></td></tr>';return parties.map(p=>`<tr><td>${esc(p.party||'Unnamed draft')}<br>${esc(p.location)} · ${esc(p.state)}</td><td>${p.calculations.length} saved calculation(s)<br>${esc([...new Set(p.calculations.map(r=>r.season))].join(', '))}</td><td>${deleted?`<button data-restore-party="${p.id}">Restore Party</button><button data-purge-kind="party" data-purge-id="${esc(p.id)}">Permanently Delete…</button>`:`<button data-open="${p.id}" class="primary">Open Party / Ledger (${p.entries?.length||0} entries)</button><button data-party-new="${p.id}">New Calculation — name/address only</button><button data-delete-party="${p.id}">Delete Party</button>`}<button data-party-history="${p.id}">Saved Calculations</button></td></tr>`).join('');}
function partiesPage(){const parties=partyList(showDeletedParties);$('#main').innerHTML=`${pageHead(showDeletedParties?'Deleted Parties':'Parties','Find a saved party, import ledgers or continue a calculation.','PARTY DIRECTORY')}<p>Open Party / Ledger shows saved vouchers directly. New Calculation — name/address only intentionally starts an empty draft. Deletion moves all its saved calculations to Deleted Parties; Restore brings them back.</p><div class="actions page-toolbar"><button data-action="new" class="primary">New Party / Calculation</button><button data-page="Bulk Import">Bulk Import PDFs</button><button id="toggle-deleted-parties">${showDeletedParties?'Show Active Parties':'Deleted Parties'}</button><input id="party-search" type="search" placeholder="Search party, location or state" aria-label="Search parties"></div><div class="card tablewrap"><table><tr><th>Party</th><th>Saved calculations</th><th>Actions</th></tr><tbody id="party-rows">${partyRows(parties)}</tbody></table></div>`;$('#party-search').oninput=e=>$('#party-rows').innerHTML=partyRows(parties.filter(p=>[p.party,p.location,p.state].join(' ').toLowerCase().includes(e.target.value.toLowerCase())));}
function partyPicker(){const parties=partyList();modal(`<h2>Select a Saved Party</h2><input id="party-picker-search" placeholder="Search party or location"><table><tbody id="party-picker-rows">${partyRows(parties,false)}</tbody></table>`);$('#party-picker-search').oninput=e=>$('#party-picker-rows').innerHTML=partyRows(parties.filter(p=>[p.party,p.location,p.state].join(' ').toLowerCase().includes(e.target.value.toLowerCase())),false);}
async function startForParty(id){mappingCropChoices={};const saved=state.records.find(r=>r.id===id&&!r.deleted_at);if(!saved)throw Error('Party no longer available. Refresh the list.');clearTimeout(saveTimer);await saveQueue;if(record?.status==='draft'&&(record.entries.length||record.party))await saveDraft();record={...blank(),party:saved.party,location:saved.location||'',state:saved.state||'',selected_party_id:saved.id};editEpoch++;page='Calculate CN';step=0;$('#modal').close();await calculate();render();}
function partyHistory(id){const base=state.records.find(r=>r.id===id);const rows=state.records.filter(r=>partyKey(r)===partyKey(base));modal(`<h2>${esc(base.party||'Unnamed draft')} — Saved Calculations</h2><p>${base.deleted_at?'Party deleted; restore it to resume calculations. Frozen results and issued controls are retained.':'Choose the calculation to continue.'}</p><table><tr><th>Season / status</th><th>Saved</th><th>Final / ledger balance</th><th></th></tr>${rows.map(r=>`<tr><td>${esc(r.season)} · ${esc(r.status)}</td><td>${esc(new Date(r.saved_at).toLocaleString('en-IN'))}</td><td>${money(r.result?.final_balance??r.closing)}</td><td>${!r.deleted_at?`<button data-open="${r.id}">Open / Continue</button>`:'Retained in deleted history'}</td></tr>`).join('')}</table>`);}
async function preparePartyRemoval(id,restore=false){clearTimeout(saveTimer);await saveQueue;if(record?.status==='draft'&&record.id&&!record.deleted_at)await saveDraft();const preview=await api('/api/party-delete',{id,restore});partyRemovalPending={id,restore,expected:preview.expected};modal(`<h2>${restore?'Restore':'Delete'} Party: ${esc(preview.party)}</h2><p>${esc(preview.location)} · ${preview.records} saved calculation(s), including ${preview.issued} issued record(s).</p><p>${restore?'All these saved calculations will return to the active party list.':'All seasons/versions for this party will move to Deleted Parties. Saved source data, frozen results and issued-CN duplicate controls are retained. You can restore this party later.'}</p><button id="confirm-party-removal" class="primary">${restore?'Restore Party':'Delete Party'}</button>`);}
async function commitPartyRemoval(){const action=partyRemovalPending;if(!action)return;const selected=state.records.find(r=>r.id===action.id);await api('/api/party-delete',{...action,confirm:true});editEpoch++;clearTimeout(saveTimer);if(record&&partyKey(record)===partyKey(selected))record=null;await refresh();page='Parties';showDeletedParties=action.restore?false:true;partyRemovalPending=null;$('#modal').close();render();toast(action.restore?'Party restored.':'Party moved to Deleted Parties.');}
async function removeScheme(id,restore=false){const sc=settingDraft.schemes.find(s=>s.id===id);if(!sc)return;if(!confirm(restore?'Restore '+sc.name+'?':'Delete '+sc.name+' from scheme selection? You can restore it later. Frozen calculations stay unchanged; drafts using it need another scheme or restoration.'))return;settingDraft=await api('/api/settings',settingDraft);settingDraft=await api('/api/scheme-delete',{id,version:settingDraft.version,restore});await refresh();showDeletedSchemes=!restore;settingsPage();toast(restore?'Scheme restored.':'Scheme moved to Deleted Schemes.');}
function summaryPanel(){return `<div class="card summary grid"><label>Ledger before new CN<span class="stat">${money(result.ledger_closing)}</span></label><label>Separate proposed CNs<span class="stat">${money(result.new_CN_total)}</span></label><label>${Number(result.final_balance)>=0?'Party still owes':'Excess party credit'}<span class="stat">${money(Math.abs(Number(result.final_balance)))}</span></label><label>Amount still unallocated ${money(result.unallocated)}</label><label>${result.issues.length} blocking review item(s)</label><label>${esc(record.status)} · ${esc(record.season)}</label></div>`}
function workspace(){if(!record){$('#main').innerHTML='<h1>Calculate CN</h1><button data-action="new">New Calculation</button>';return}$('#main').innerHTML=`<div class="workspace-title"><span class="eyebrow">${step===2?'PAYMENT STUDIO':'CN WORKSPACE'}</span><h1>${esc(record.party||'New Calculation')}</h1></div>${workingPeriodBanner()}${workbookAddressNotice()}${emptyDraftNotice()}<p>${esc(record.location)} · ${esc(record.state)} · ${esc(record.season)}</p>${summaryPanel()}${workflowNextHTML()}<div class="tabs calculation-steps" aria-label="Calculation steps">${steps.map((x,i)=>`<button data-step="${i}" class="${step===i?'active':''}" ${step===i?'aria-current="step"':''}><span class="step-number">${i+1}</span><span>${x}<small class="workflow-step-state">${workflowStepStates()[i]}</small></span></button>`).join('')}</div><div id="work">${[partyTab,ledgerTab,paymentTab,benefitTab,finishTab][step]()}</div><div class="actions workflow-footer"><button data-action="back" ${step===0?'disabled':''}>Back</button><button data-action="save" ${record.status!=='draft'?'disabled':''}>Save Draft</button><button class="primary" data-action="next" ${step===4?'disabled':''}>Next</button></div>`;if(record.status!=='draft'||record.deleted_at)$('#work').querySelectorAll('input,select,textarea,button[data-edit]').forEach(x=>x.disabled=true);globalThis.requestAnimationFrame?.(refreshAllocationFlow)}
function partyTab(){return `<div class="card party-intake"><span class="eyebrow">01 / PARTY & SOURCE</span><h2>Select Party</h2><div class="actions"><label>Open an existing party ledger<select id="saved-party">${option('','Select saved party','')}${partyList().map(p=>option(p.id,p.party+' · '+(p.location||p.state||'Location not entered'),'' )).join('')}</select></label><button data-action="party-picker" data-edit>Search Party List</button></div><p>Choosing a saved party opens its saved ledger and entries. Use the separately labelled New Calculation option only to start a blank calculation with its name/address.</p><div class="grid">${field('Party name','party',record.party)}${field('Location','location',record.location)}${field('Address state','state',record.state)}<label>Season<select data-field="season">${state.settings.seasons.map(s=>option(s.name,s.name,record.season))}</select></label></div>${record.party_details?.address?`<p class="muted">Statement address: ${esc(record.party_details.address)}. Check the suggested party details above.</p>`:''}<details><summary>Use another state's scheme</summary><div class="grid two">${field('Scheme state override (optional)','scheme_state',record.scheme_state)}${field('Reason for state override','override_reason',record.override_reason)}</div></details><div class="actions"><label>Import Tally PDF<input type="file" id="pdf" accept="application/pdf" ${record.status!=='draft'?'disabled':''}></label><button data-action="fixture" data-edit>Use Ashapura fixture</button><button data-step="1">Enter Manually</button></div><p>Check your ledger first. The applicable schemes appear below after products are mapped.</p></div>${simpleSchemeCards()}`}
function calculationSettings(){const cfg=structuredClone(record?.frozen_settings||state.settings);for(const [pid,sid] of Object.entries(record?.product_assignments||{})){const p=cfg.products.find(p=>p.id===pid),base=cfg.schemes.find(s=>s.id===sid),dest=cfg.schemes.find(s=>s.id===(record.scheme_overrides?.[sid]||sid));if(!p||!base||!dest)continue;p.scheme=sid;p.segment=dest.segment;p.segment_id=dest.segment_id||dest.segment;p.needs_assignment=false;for(const target of [base,dest])if(!target.products.includes(pid))target.products.push(pid);}return cfg;}
function soldProductIds(){const cfg=calculationSettings();const season=cfg.seasons.find(s=>s.name===record?.season);const quantities=new Map();for(const e of record?.entries||[]){if(!['sale','return','ipt_in','ipt_out'].includes(e.kind))continue;const dt=(e.original||e).date;if(season?.confirmed&&season.start&&season.end&&dt&&!entrySelectedForStock(e,season))continue;for(const i of e.items||[]){const p=cfg.products.find(p=>p.id===i.product);if(!p||i.exclude)continue;const qty=Number(i.qty)*(i.unit==='packet'?Number(p.packing_kg):1);quantities.set(p.id,(quantities.get(p.id)||0)+(['sale','ipt_in'].includes(e.kind)?qty:-qty));}}return new Set([...quantities].filter(([id,q])=>q>0).map(([id])=>id));}
function baseSegments(){const cfg=calculationSettings();const sold=soldProductIds();const ids=new Set(cfg.products.filter(p=>sold.has(p.id)).map(p=>p.scheme));return [...ids].map(id=>cfg.schemes.find(s=>s.id===id)).filter(Boolean)}
function allocationSchemes(type){const cfg=calculationSettings();if(type==='Settlement')return cfg.schemes.filter(s=>!s.deleted_at&&!s.mapping_placeholder);const sold=soldProductIds();return cfg.schemes.filter(s=>!s.deleted_at&&!s.mapping_placeholder&&s.season===record.season&&s.products.some(id=>sold.has(id))&&(type!=='Cash'||s.cash)&&(type!=='Net'||s.benefits.includes('Net')||s.cash));}
function defaultAllocationScheme(type='CD'){const all=allocationSchemes(type);const choices=type==='ABS'?all.filter(s=>s.benefits.includes('ABS')):all;return choices.find(s=>Object.values(record.scheme_overrides||{}).includes(s.id))?.id||choices[0]?.id||'';}
// Exact decimal comparison for receipt splits, including fractional rupees.
function decimalParts(value){const m=String(value??'0').match(/^([+-]?)(\d*)(?:\.(\d*))?(?:e([+-]?\d+))?$/i);if(!m||(!m[2]&&!m[3]))throw Error('Enter a valid amount.');const exp=Number(m[4]||0);if(Math.abs(exp)>100)throw Error('Amount is too large.');const digits=(m[2]||'0')+(m[3]||'');let scale=(m[3]||'').length-exp;let n=BigInt(digits)*(m[1]==='-'?-1n:1n);if(scale<0){n*=10n**BigInt(-scale);scale=0;}return {n,scale};}
function absSourceAllowed(source,scheme){if(!source)return false;const dt=source.date;if(source.opening&&!dt)return true;if(!scheme?.benefits?.includes('ABS'))return false;if(!dt)return false;return !!((scheme.abs_start&&scheme.abs_end&&scheme.abs_start<=dt&&dt<=scheme.abs_end)||(scheme.abs_end&&scheme.extended_end&&scheme.abs_end<dt&&dt<=scheme.extended_end));}
function absAllocationError(a){if(a.type!=='ABS')return '';const source=result.sources.find(s=>s.id===a.source),sc=calculationSettings().schemes.find(s=>s.id===a.scheme);return absSourceAllowed(source,sc)?'':'ABS not allowed for original payment date '+(source?.date?date(source.date):'missing')+'. Choose a receipt within this scheme’s ABS booking period, or use CD / Settlement.';}
function allocationLimitError(candidate,index){try{if(record.manual_order&&candidate.type==='CD'&&candidate.order!==''&&candidate.order!=null&&!/^\d+$/.test(String(candidate.order)))return 'CD processing order must be a nonnegative whole number; leave blank for 0.';const source=result.sources.find(x=>x.id===candidate.source);const amount=decimalParts(candidate.amount||'0');if(amount.n<0n)return 'Amount must be zero or positive.';if(!source)return amount.n===0n?'':'Choose an existing payment source.';const parts=[decimalParts(source.available),...record.allocations.filter((a,i)=>i!==index&&a.source===candidate.source).map(a=>decimalParts(a.amount||'0')),amount];const scale=Math.max(...parts.map(p=>p.scale));const values=parts.map(p=>p.n*10n**BigInt(scale-p.scale));if(values.slice(1).reduce((a,b)=>a+b,0n)>values[0])return 'This split exceeds '+money(source.available)+' available after old dues. Reduce another split first.';return absAllocationError(candidate);}catch(e){return e.message;}}
function allocationRemaining(a,i){const src=result.sources.find(s=>s.id===a.source);return Math.max(0,Number(src?.available||0)-record.allocations.reduce((n,x,j)=>n+(j!==i&&x.source===a.source?Number(x.amount||0):0),0));}
function applicableChoices(base){return calculationSettings().schemes.filter(s=>!s.deleted_at&&!s.mapping_placeholder&&s.crop===base.crop&&(s.segment_id&&base.segment_id?s.segment_id===base.segment_id:s.segment===base.segment)&&s.season===record.season)}
const benefitNames={Net:'Net Rate',ABS:'Advance Booking (ABS)',Quantity:'Quantity Discount',CD:'Payment Discount (CD)',Extra:'Trip / Extra Benefit',Return:'No / Low Return Bonus'};
const schemeMoney=x=>x===null||x===undefined||x===''?'Not entered':money(x);
const schemeDate=x=>x?date(x):'Not entered';
function rateSummary(sc){return sc.benefits.map(b=>b==='ABS'?`${benefitNames[b]}: token ${schemeMoney(sc.token)} / ${sc.abs_unit}; CN ${schemeMoney(sc.abs_rate)} / ${sc.abs_unit}`:b==='Quantity'?`${benefitNames[b]}: ${sc.quantity?.length||0} slabs`:b==='CD'?`${benefitNames[b]}: ${sc.cd?.length||0} periods`:b==='Extra'?`${benefitNames[b]}: ${sc.extra?.length||0} slabs`:b==='Return'?`${benefitNames[b]}: up to ${sc.return_threshold}% returns, ${schemeMoney(sc.return_rate)} / ${sc.return_unit}`:sc.net_mode==='fixed'?`${benefitNames[b]}: fixed ${schemeMoney(sc.net_cn_rate)} / ${sc.net_cn_unit}`:`${benefitNames[b]}: ${sc.net?.length||0} slabs`).join('<br>')}
function simpleSchemeCards(){let bases=baseSegments().filter(s=>!s.mapping_placeholder);if(!bases.length)return missingSchemePanel();return missingSchemePanel()+`<div class="card"><h2>Your selected schemes</h2><p>One scheme for each crop and segment. Change a scheme only when you need a different saved setup.</p><div class="grid two">${bases.map(base=>{let chosen=calculationSettings().schemes.find(s=>s.id===(record.scheme_overrides?.[base.id]||base.id))||base;return `<div class="scheme-card"><h3>${esc(base.crop+' / '+base.segment)}</h3><strong>${esc(chosen.name)}</strong><p>${chosen.benefits.map(b=>esc(benefitNames[b]||b)).join(' + ')}</p><span class="pill">${chosen.confirmed?'Confirmed setup':'Draft setup — needs confirmation'}</span><details><summary>View rates and slabs</summary>${rateSummary(chosen)}</details><p class="cash-setup-state">Cash option: <strong>${chosen.cash?'Configured':'Not configured'}</strong></p><button data-configure-cash="${esc(chosen.id)}" ${record.status!=='draft'?'disabled':''}>${chosen.cash?'Edit Cash settings':'Configure Cash option'}</button><small class="cell-note">Settings apply to this workbook’s scheme. Allocate quantity separately for this party.</small><button data-change-scheme="${base.id}" ${record.status!=='draft'?'disabled':''}>Change Scheme</button></div>`}).join('')}</div></div>`}
function chooseScheme(id){let base=calculationSettings().schemes.find(s=>s.id===id),choices=applicableChoices(base);modal(`<h2>Choose scheme: ${esc(base.crop+' / '+base.segment)}</h2><p>Choose a saved setup for ${esc(record.season)}. The actual ledger and receipt dates stay unchanged.</p>${choices.map(sc=>`<div class="scheme-card"><h3>${esc(sc.name)}</h3><p>${sc.benefits.map(b=>esc(benefitNames[b]||b)).join(' + ')}</p><p>Applies in: ${esc(sc.states.join(', ')||'States not entered yet')}</p><details><summary>View rates</summary>${rateSummary(sc)}</details><button data-use-scheme="${sc.id}" data-base="${base.id}">Use this scheme</button></div>`).join('')||'<div class="warn">No saved scheme for this segment and season. Add one under Settings.</div>'}<p>Create or edit scheme rates under Settings → My Schemes.</p>`)}
function productOptions(selected){return option('','Needs mapping',selected)+(record.frozen_settings||state.settings).products.filter(p=>!p.deleted_at||p.id===selected).map(p=>option(p.id,`${p.crop} / ${p.segment} / ${p.name} / ${p.packing_kg} kg`,selected)).join('')}
function productTotals(){let t={};for(let e of record.entries)for(let i of e.items||[]){let k=i.name+'|'+i.unit;if(!t[k])t[k]={name:i.name,unit:i.unit,s:0,r:0};if(e.kind==='sale')t[k].s+=Number(i.qty);if(e.kind==='return')t[k].r+=Number(i.qty)}return Object.values(t)}
let mappingCropChoices={};
function stockRows(){const cfg=calculationSettings(),rows=new Map(),period=cfg.seasons.find(s=>s.name===record.season);for(const e of record.entries){const dt=(e.original||e).date;if(record.annual_ledger&&period?.confirmed&&period.start&&period.end&&dt&&!entrySelectedForStock(e,period))continue;if(!['sale','return','ipt_in','ipt_out'].includes(e.kind))continue;for(const item of e.items||[]){if(item.exclude)continue;const p=cfg.products.find(p=>p.id===item.product),key=JSON.stringify([p?.id||item.name,item.unit]);if(!rows.has(key))rows.set(key,{crop:p?.crop||item.mapping_crop||'Unmapped',product:p?.name||item.name,packing:p?.packing_kg||item.mapping_suggestion?.detected_packing_kg,unit:item.unit,supply:0,ipt_in:0,ipt_out:0,returned:0,entries:new Set()});const row=rows.get(key);row[{sale:'supply',return:'returned',ipt_in:'ipt_in',ipt_out:'ipt_out'}[e.kind]]+=Number(item.qty||0);row.entries.add(e.id);}}return [...rows.values()].map(r=>({...r,net_supply:r.supply+r.ipt_in-r.ipt_out,net_sold:r.supply+r.ipt_in-r.ipt_out-r.returned}));}
function stockQty(x){return Number(x||0).toLocaleString('en-IN',{maximumFractionDigits:6});}
function stockSummary(){const rows=stockRows();if(!rows.length)return '';const totals=new Map();for(const r of rows){const key=JSON.stringify([r.crop,r.unit]);if(!totals.has(key))totals.set(key,{crop:r.crop,unit:r.unit,supply:0,ipt_in:0,ipt_out:0,net_supply:0,returned:0,net_sold:0});const t=totals.get(key);for(const k of ['supply','ipt_in','ipt_out','net_supply','returned','net_sold'])t[k]+=r[k];}const columns=[['supply','Supply'],['ipt_in','IPT In'],['ipt_out','IPT Out'],['net_supply','Net Supply'],['returned','Sales Return'],['net_sold','Net Sold']];const exceptions=record.entries.filter(e=>e.classification_required||e.kind==='unknown');return `<section class="card stock-summary"><h2>Supply & Stock Summary</h2><p><strong>Net Supply = Supply + IPT In − IPT Out</strong><br><strong>Net Sold = Net Supply − Sales Return</strong></p><p class="muted">${record.annual_ledger?'Selected working-period quantities, including explicitly reviewed late IPT; full-year vouchers and original dates remain saved.':'Full statement quantities, excluding documented excluded items.'} Each voucher contributes once to its own column. Quantities in kg and packets are shown separately. Season/date exceptions still need correction before CN finalisation.</p>${[...totals.values()].map(t=>`<h3>${esc(t.crop)} · ${esc(t.unit)}</h3><div class="stock-metrics">${columns.map(([key,label])=>`<div class="stock-metric ${key.startsWith('net_')?'stock-net':''}"><span>${label}</span><strong>${stockQty(t[key])}</strong></div>`).join('')}</div>`).join('')}${exceptions.length?`<p class="warn">${exceptions.length} voucher(s) need classification; unresolved stock is not included in these totals. Open the flagged entry under Review & Finish.</p>`:''}<div class="tablewrap"><table class="stock-table"><thead><tr><th>Crop / Product</th><th>Packing / Qty unit</th>${columns.map(([key,label])=>`<th class="${key.startsWith('net_')?'stock-net':''}">${label}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><small>${esc(r.crop)}</small><br><strong>${esc(r.product)}</strong></td><td>${r.packing?esc(r.packing)+' kg / packet<br>':''}${esc(r.unit)}</td>${columns.map(([key])=>`<td class="${key.startsWith('net_')?'stock-net':''} ${r[key]<0?'stock-negative':''}">${stockQty(r[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">Expand a voucher below to see or correct its source entry. Routine voucher and mapping verification ticks are no longer required.</p></section>`;}
function mappingGroups(){const groups=new Map(),period=calculationSettings().seasons.find(s=>s.name===record.season);for(const [ei,e] of record.entries.entries()){const dt=(e.original||e).date;if(record.annual_ledger&&period?.confirmed&&period.start&&period.end&&dt&&!entrySelectedForStock(e,period))continue;if(!['sale','return','ipt_in','ipt_out'].includes(e.kind))continue;for(const [ii,item] of (e.items||[]).entries()){if(item.exclude)continue;const key=JSON.stringify([item.name,item.unit]);if(!groups.has(key))groups.set(key,{key,name:item.name,unit:item.unit,supplied:0,ipt_in:0,ipt_out:0,returned:0,items:[]});const g=groups.get(key);g[{sale:'supplied',return:'returned',ipt_in:'ipt_in',ipt_out:'ipt_out'}[e.kind]]+=Number(item.qty||0);g.items.push({item,entry:e,ei,ii});}}return [...groups.values()];}
function mappingSummary(){const cfg=record.frozen_settings||state.settings;const groups=mappingGroups();return `<h3>Product Mapping</h3><p>Choose crop, product and packing. Save Mapping stores the product and this statement name in the main catalogue for future parties. Scheme selection stays specific to this calculation. No per-entry tick is needed.</p><div class="tablewrap"><table><tr><th>Statement product</th><th>Crop</th><th>Product name</th><th>Packing (kg per packet)</th><th>Mapping status / scheme</th></tr>${groups.map((g,index)=>{const ids=[...new Set(g.items.map(x=>x.item.product))];const selected=ids.length===1?ids[0]:'';const p=cfg.products.find(p=>p.id===selected);const first=g.items[0].item,suggestion=first.mapping_suggestion;const crop=first.mapping_crop||mappingCropChoices[g.key]||p?.crop||suggestion?.crop||'';const name=p?.name||first.mapping_name||g.name;const pack=p?.packing_kg||first.mapping_packing||suggestion?.detected_packing_kg||'';const confirmed=Boolean(p)&&g.items.every(x=>x.item.mapping_confirmed!==false);const crops=[...new Set([...(cfg.crops||[]),...cfg.products.map(p=>p.crop)])];const names=[...new Set(cfg.products.filter(p=>!p.deleted_at&&(!crop||p.crop===crop)).map(p=>p.name))];return `<tr><td><strong>${esc(g.name)}</strong><br><small>${esc(suggestion?.reason||'Check saved mapping')}</small></td><td><select data-map-crop="${index}" aria-label="Crop for ${esc(g.name)}">${option('','Choose crop',crop)}${crops.map(c=>option(c,c,crop)).join('')}${option('__new__','+ Add / Name New Crop',crop)}</select><button data-inline-map="${index}" data-edit>Add / Edit Crop</button></td><td><input data-map-name="${index}" list="mapping-names-${index}" value="${esc(name)}" aria-label="Product name for ${esc(g.name)}"><datalist id="mapping-names-${index}">${names.map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></td><td><input type="number" min="0.000001" step="any" data-map-pack="${index}" value="${esc(pack)}" aria-label="Packing for ${esc(g.name)}">${suggestion?.detected_packing_kg?`<small>Statement suggests ${esc(suggestion.detected_packing_kg)} kg</small>`:''}<button data-inline-map="${index}" data-edit>Save / Edit Mapping</button></td><td><span class="pill">${ids.length>1?'Mixed choices — edit affected voucher':p?'Mapped':'Mapping needed'}</span>${p?`<button data-product-scheme="${p.id}" data-edit>Choose Scheme / Group</button>`:''}</td></tr>`;}).join('')}</table></div>`;}
let inlineMappingIndex=null,mappingSchemeProduct=null;
function inlineMappingEditor(index,newCrop=false){inlineMappingIndex=index;const g=mappingGroups()[index],first=g.items[0].item,p=state.settings.products.find(p=>p.id===first.product);settingDraft=structuredClone(state.settings);const crops=catalogCrops();modal(`<h2>Edit Product Mapping</h2><p>${esc(g.name)}</p><div class="grid two"><label>Saved crop<select id="im-crop">${option('','Choose crop',first.mapping_crop||p?.crop||'')}${crops.map(c=>option(c,c,first.mapping_crop||p?.crop||'')).join('')}</select></label><label>Or name a new crop<input id="im-new-crop" placeholder="For example: Redgram"></label><label>Product name<input id="im-name" value="${esc(p?.name||first.mapping_name||g.name)}"></label><label>Packing: kg per packet<input id="im-pack" type="number" min="0.000001" step="any" value="${esc(first.mapping_packing||first.mapping_suggestion?.detected_packing_kg||sourcePacking(g.name)||p?.packing_kg||'')}"></label></div><p>Packing is suggested only when printed explicitly in the source product name. Review it before saving; ambiguous/missing packing stays editable.</p><p>Product and packing are saved first. You choose its group through the scheme afterward. A changed packing creates a separate catalogue variant.</p><button id="save-inline-mapping" class="primary">Save Mapping</button>`);}
function mappingValues(index){const g=mappingGroups()[index],first=g.items[0].item,p=state.settings.products.find(p=>p.id===first.product);return {crop:first.mapping_crop||mappingCropChoices[g.key]||p?.crop||first.mapping_suggestion?.crop||'',name:p?.name||first.mapping_name||g.name,packing:first.mapping_packing||first.mapping_suggestion?.detected_packing_kg||sourcePacking(g.name)||p?.packing_kg||''};}
async function saveInlineMapping(index,values){const g=mappingGroups()[index];const crop=values.crop.trim(),name=values.name.trim(),packing=String(values.packing).trim();if(!crop||!name)throw Error('Enter crop and product name.');if(crop.toLowerCase()==='all')throw Error('Use a crop name other than All.');if(!Number.isFinite(Number(packing))||Number(packing)<=0)throw Error('Enter a positive packing weight in kg.');const draft=structuredClone(state.settings);const known=[...(draft.crops||[]),...draft.products.map(p=>p.crop),...draft.schemes.map(s=>s.crop)].find(c=>c.toLowerCase()===crop.toLowerCase());const chosenCrop=known||crop;draft.crops=[...new Set([...(draft.crops||[]),chosenCrop])];let product=draft.products.find(p=>p.crop===chosenCrop&&p.name.toLowerCase()===name.toLowerCase()&&Number(p.packing_kg)===Number(packing));if(!product){const id=uid(),sid=uid(),segment=uid();product={id,name,crop:chosenCrop,packing_kg:packing,scheme:sid,segment:'Awaiting scheme',segment_id:segment,aliases:[g.name],needs_assignment:true};const scheme={id:sid,segment_id:segment,version:1,name:'Awaiting scheme — '+name,crop:chosenCrop,segment:'Awaiting scheme',season:record.season,states:[],confirmed:false,unit:g.unit,packing_kg:packing,billing:null,billing_unit:g.unit,benefits:[],quantity_mode:'whole',quantity:[],extra:[],extra_unit:'fixed',token:null,abs_rate:null,abs_unit:g.unit,abs_start:null,abs_end:null,extended_end:null,cd:[],return_threshold:'0',return_rate:null,return_unit:g.unit,net:[],cash:null,products:[id],mapping_placeholder:true,narration:'{party} | {crop} | {segment} | {season} | {benefit}'};draft.products.push(product);draft.schemes.push(scheme);}product.aliases=[...new Set([...(product.aliases||[]),g.name])];settingDraft=await api('/api/settings',draft);await refresh();mappingCropChoices[g.key]=chosenCrop;for(const {item,entry} of g.items){item.product=product.id;item.mapping_crop=chosenCrop;item.mapping_name=product.name;item.mapping_packing=packing;item.mapping_confirmed=false;item.mapping_reason='Crop, product and packing edited during statement review';entry.reviewed=false;}changed();await calculate();render();return product;}
async function commitInlineMapping(){await saveInlineMapping(inlineMappingIndex,{crop:$('#im-new-crop').value.trim()||$('#im-crop').value,name:$('#im-name').value,packing:$('#im-pack').value});$('#modal').close();toast('Mapping saved in the main catalogue. Choose a scheme/group under Check Benefits.');}
function missingSchemePanel(){if(!record)return '';const cfg=record.frozen_settings||state.settings;const pending=mappingGroups().filter(g=>{const p=cfg.products.find(p=>p.id===g.items[0].item.product);if(!p)return true;const assigned=record.product_assignments?.[p.id],target=cfg.schemes.find(s=>s.id===(record.scheme_overrides?.[assigned||p.scheme]||assigned||p.scheme));return (p.needs_assignment&&!assigned)||!target||target.deleted_at||target.mapping_placeholder;});if(!pending.length)return '';return `<div class="card warn"><h2>Scheme selection needed</h2><p>These statement products still need crop/product mapping or a scheme/group. They receive no calculated benefit until resolved.</p>${pending.map(g=>{const first=g.items[0].item,p=cfg.products.find(p=>p.id===first.product);return `<p><strong>${esc(p?.crop||first.mapping_crop||'Crop not yet mapped')} / ${esc(p?.name||g.name)}</strong> ${p?`<button data-product-scheme="${p.id}" data-edit>Choose Scheme / Group</button>`:`<button data-inline-map="${mappingGroups().findIndex(x=>x.key===g.key)}" data-edit>Map Crop / Product</button>`}</p>`;}).join('')}</div>`;}
function chooseProductScheme(pid){const p=state.settings.products.find(p=>p.id===pid);const choices=state.settings.schemes.filter(s=>!s.deleted_at&&!s.mapping_placeholder&&s.crop===p.crop&&Number(s.packing_kg)===Number(p.packing_kg)&&s.season===record.season);modal(`<h2>Choose Scheme / Group for ${esc(p.name)}</h2><p>${esc(p.crop)} · ${esc(p.packing_kg)} kg per packet · ${esc(record.season)}</p>${choices.map(s=>`<div class="scheme-card"><h3>${esc(s.name)}</h3><p>Group: ${esc(s.segment)} · ${esc(s.states.join(', ')||'States not yet confirmed')}</p><button data-assign-product="${pid}" data-assign-scheme="${s.id}">Use This Scheme / Group</button></div>`).join('')||'<p class="warn">No compatible saved scheme for this crop, packing and season.</p>'}<button data-create-product-scheme="${pid}" class="primary">Create Scheme for This Product</button>`);}
async function assignProductScheme(pid,sid){record.product_assignments=record.product_assignments||{};record.product_assignments[pid]=sid;changed();$('#modal').close();await calculate();render();toast('Scheme/group assigned to this product for this calculation. Check existing payment destinations after a group change.');}
function createProductScheme(pid){settingDraft=structuredClone(state.settings);const p=settingDraft.products.find(p=>p.id===pid),base=settingDraft.schemes.find(s=>s.id===p.scheme);builder=structuredClone(base);builder.id=uid();builder.segment_id=uid();builder.segment=p.crop+' '+p.packing_kg+' kg';builder.name=p.crop+' — '+p.name+' Scheme';builder.products=[pid];builder.season=record?.season||settingDraft.seasons[0]?.name;builder.states=record?.state?[record.state]:[];builder.confirmed=false;builder.record_product_scheme=true;const hint=sourceSaleRates(pid,builder.unit,p.packing_kg);builder.pdf_rate_options=hint;builder.pdf_rate_unit=builder.unit;if(hint.length===1){builder.billing=hint[0];builder.billing_unit=builder.unit;builder.pdf_rate_note='Prefilled from a single source sales rate; verify before confirming';}else if(hint.length>1){builder.billing=null;builder.billing_unit=builder.unit;builder.pdf_rate_note='Mixed source sales rates: choose a rate explicitly; no rate was guessed';}if(base.mapping_placeholder){builder.net_mode='fixed';builder.net_cn_rate=null;builder.net_cn_unit='packet';}delete builder.mapping_placeholder;delete builder.deleted_at;indexEditing=null;mappingSchemeProduct=record?.status==='draft'?pid:null;wizardStep=0;wizardErrors=[];builderForm();}
function updateGroupMapping(index,productId){const group=mappingGroups()[index];if(!group)return;for(const {item,entry} of group.items){item.product=productId||null;const selected=state.settings.products.find(p=>p.id===productId);if(selected){item.mapping_crop=selected.crop;item.mapping_name=selected.name;item.mapping_packing=selected.packing_kg;}item.mapping_confirmed=false;item.mapping_reason='Mapping selected during statement review';entry.reviewed=false;}changed();}
function confirmGroupMapping(index,value){const group=mappingGroups()[index],cfg=record.frozen_settings||state.settings;if(!group)return;const ids=[...new Set(group.items.map(x=>x.item.product))];const p=ids.length===1&&cfg.products.find(p=>p.id===ids[0]);if(value&&!p)throw Error('Select the correct product and packing before confirming.');for(const {item} of group.items){if(value&&item.mapping_suggestion?.detected_packing_kg&&Number(item.mapping_suggestion.detected_packing_kg)!==Number(p.packing_kg)){if(!confirm('Statement packing differs from '+p.name+' / '+p.packing_kg+' kg. Confirm this mapping correction?'))return;break;}}for(const {item} of group.items){item.mapping_confirmed=value;item.mapping_reason=value?'Product, crop and packing checked by user':'Mapping awaiting review';}changed();}
function ledgerTab(){return lateIPTPanel()+stockSummary()+`<div class="card ledger-review"><span class="eyebrow">02 / VERIFY THE LEDGER</span><h2>Check Ledger</h2><div class="grid">${field('Opening debit (+) / credit (−)','opening',record.opening,'number')}${field('Full-statement closing debit (+) / credit (−)','closing',record.closing,'number')}${field('Confirmed old outstanding to clear','old_dues',record.old_dues,'number')}</div><p>Computed closing: ${money(result.ledger_computed)} · Difference: ${money(result.mismatch)}</p>${mappingSummary()}<div class="actions"><button data-action="add-entry" data-edit>Add manual voucher</button><button data-action="review-ledger" data-edit>Confirm stock summary</button>${record.source?.text?'<button data-action="reparse-source" data-edit>Re-read Statement / Review Missing Returns</button>':''}</div>${record.parent?chk('Current revised ledger includes previously issued CNs','revision_ledger_confirmed',record.revision_ledger_confirmed):''}${record.ledger_confirmed?'<div class="ok">Stock summary confirmed</div>':'<div class="warn">Check the stock summary, resolve missing mappings / exceptions, then confirm once.</div>'}</div>${['sale','return','ipt_in','ipt_out','receipt','posted_cn','adjustment','unknown'].map(kind=>`<div class="card"><h2>${{sale:'Products: Sales',return:'Products: Sales Returns',ipt_in:'IPT Received — adds to supply',ipt_out:'IPT Given — deducts from supply',receipt:'Payments',posted_cn:'Already-posted CNs — freight / expenses / benefits',adjustment:'Other Ledger Entries',unknown:'Needs classification'}[kind]}</h2>${record.entries.filter(e=>e.kind===kind).map(e=>voucherCard(e)).join('')||'<p class="muted">No entries</p>'}</div>`).join('')}`}
function voucherCard(e){let idx=record.entries.indexOf(e);return `<details id="voucher-${idx}"><summary>${date(e.date)} · ${esc(e.reference)} · ${esc(e.posting_label||entryLabels[e.kind]||e.kind)} · ${money(Number(e.debit)-Number(e.credit))} · ${e.classification_required?'Classification needed':'Included in summary'}</summary><div class="grid">${entryField(idx,'date','Original/reviewed date',e.date,'date')}${entryField(idx,'reference','Reference',e.reference)}${entryField(idx,'debit','Debit',e.debit,'number')}${entryField(idx,'credit','Credit',e.credit,'number')}<label>Type<select data-entry="${idx}" data-key="kind">${Object.keys(entryLabels).map(k=>option(k,entryLabels[k],e.kind)).join('')}</select></label>${entryField(idx,'correction_reason','Correction / review reason',e.correction_reason)}</div>${['return','ipt_in','ipt_out','unknown','adjustment','posted_cn'].includes(e.kind)?`<div class="actions"><button data-classify-entry="${idx}" data-edit>Sales Return / IPT / Posting</button><small>${e.classification_required?'Classification needs review':''}</small></div>`:''}${e.kind.startsWith('ipt_')?`${entryField(idx,'transfer_party','Other seller / transfer reference (optional)',e.transfer_party)}<p>Adjusted supply = invoice supply + IPT received − IPT given. Actual returns remain separate.</p>`:''}<div class="tablewrap"><table><tr><th>Original item</th><th>Product / packing mapping</th><th>Quantity / unit</th><th>Rate / amount</th><th>Exclude with reason</th></tr>${(e.items||[]).map((i,j)=>`<tr id="voucher-item-${idx}-${j}"><td>${esc(i.name)}${isManualItem(e,i)?`<button data-delete-item="${idx},${j}" data-edit>Delete Manual Item</button>`:''}</td><td><select data-item="${idx},${j}" data-key="product">${productOptions(i.product)}</select></td><td><input type="number" data-item="${idx},${j}" data-key="qty" value="${esc(i.qty)}"><select data-item="${idx},${j}" data-key="unit">${['kg','packet'].map(u=>option(u,u,i.unit)).join('')}</select></td><td><input type="number" data-item="${idx},${j}" data-key="rate" value="${esc(i.rate)}"><input type="number" data-item="${idx},${j}" data-key="amount" value="${esc(i.amount)}"></td><td><input type="checkbox" data-item="${idx},${j}" data-key="exclude" ${i.exclude?'checked':''}><input data-item="${idx},${j}" data-key="review_reason" value="${esc(i.review_reason)}" placeholder="Season / scope reason"></td></tr>`).join('')}</table></div><button data-add-item="${idx}" data-edit>Add item</button><details><summary>Original source voucher and lines</summary><pre>${esc(JSON.stringify(e.original||e.source_lines||'Manual entry',null,2))}</pre></details></details>`}
const entryLabels={sale:'Sale / Invoice supply',return:'Actual Sales Return',ipt_in:'IPT Received from another seller',ipt_out:'IPT Given to another seller',receipt:'Payment Received',posted_cn:'Already-posted CN — freight / expenses / other CN',adjustment:'Other Ledger Adjustment',unknown:'Needs Classification'};
function isManualItem(entry,item){return item.source_page===undefined&&item.source_line===undefined&&(item.manual===true||item.name==='Manual item'||!(entry.source_lines?.length));}
async function removeManualItem(ei,ii){const e=record.entries[ei],item=e?.items?.[ii];if(record.status!=='draft'||!item||!isManualItem(e,item))throw Error('Only manual rows can be deleted. Exclude imported items with a reason.');if(!confirm('Delete this manual item? Posted voucher amounts remain unchanged.'))return;e.items.splice(ii,1);if(!e.items.length&&!e.source_lines?.length&&Number(e.debit||0)===0&&Number(e.credit||0)===0){e.kind='adjustment';e.classification_required=false;}e.reviewed=false;$('#modal').close();e.correction_reason=(e.correction_reason?e.correction_reason+'; ':'')+'Removed manual item entered during draft preparation: '+item.name;changed();await calculate();render();toast('Manual row removed. Review the voucher totals if it contained a nonzero value.');}
function classifyEntry(index){const e=record.entries[index],season=state.settings.seasons.find(s=>s.name===record.season);const outside=season?.start&&season?.end&&(e.date<season.start||e.date>season.end);modal(`<h2>Review ${esc(e.reference||e.id)}</h2><p>${date(e.date)} · debit ${money(e.debit)} · credit ${money(e.credit)}</p><label>What is this entry?<select id="classify-kind">${option('','Choose classification',e.kind)}${Object.entries(entryLabels).filter(([k])=>['return','ipt_in','ipt_out','posted_cn','adjustment','sale'].includes(k)).map(([k,l])=>option(k,l,e.kind)).join('')}</select></label><p>IPT received adds to supply; IPT given reduces supply. Actual returns are counted separately. Source money and original dates stay unchanged.</p>${outside?`<div class="warn">This transaction date is outside ${esc(season.start)} through ${esc(season.end)}. Review the season period; the original transaction date is preserved.<button data-action="review-season-dates">Review Season Dates</button></div>`:''}${e.items.map((item,ii)=>isManualItem(e,item)?`<button data-delete-item="${index},${ii}">Delete Manual Item: ${esc(item.name)}</button>`:'').join('')}<label>Review note<input id="classify-reason" placeholder="Reason / source reference"></label><button data-confirm-classification="${index}" class="primary">Apply Classification</button>${record.source?.text?'<button data-action="reparse-source">Re-read Statement / Review Missing Items</button>':''}`);}
function applyEntryClassification(index,kind,reason=''){if(!entryLabels[kind]||kind==='unknown')throw Error('Choose the correct voucher classification.');const e=record.entries[index];e.kind=kind;if(kind!=='posted_cn')delete e.posting_label;e.classification_required=false;e.reviewed=false;e.correction_reason=reason||e.correction_reason||'Voucher classification reviewed: '+entryLabels[kind];if(e.items?.length||!['sale','return','ipt_in','ipt_out'].includes(kind))record.pending_import_reviews=(record.pending_import_reviews||[]).filter(p=>p.id!==e.id);changed();}
function reviewTarget(index){const message=result.issues[index],detail=result.issue_details?.find(d=>d.message===message)||{};let target={...detail};if(target.step===undefined){if(/season dates|cutoff|outside selected season/i.test(message))target={...target,step:1,settings_section:'seasons'};else if(/scheme|entitlement|benefit/i.test(message))target={...target,step:3};else if(/party name|address state|state override/i.test(message))target={...target,step:0};else if(/cash|allocation|payment|receipt remainder|opening credit remainder|booking period/i.test(message))target={...target,step:2};else target={...target,step:1};}if(!target.entry){const entry=record.entries.find(e=>message.includes(e.id)||e.reference&&message.includes(e.reference));if(entry)target.entry=entry.id;}if(/Map product and packing|Confirm suggested product/i.test(message)&&!target.item_name){const g=mappingGroups().find(g=>message.includes(g.name));if(g){target.item_name=g.name;target.item_unit=g.unit;target.step=1;}}return target;}
async function reviewIssue(index){const target=reviewTarget(index);step=target.step;page='Calculate CN';render();if(target.product&&!target.entry){const entry=record.entries.find(e=>e.kind==='ipt_out'&&e.items?.some(i=>i.product===target.product))||record.entries.find(e=>e.items?.some(i=>i.product===target.product));if(entry)target.entry=entry.id;}if(target.settings_section&&target.entry){const ei=record.entries.findIndex(e=>e.id===target.entry);if(ei>=0){classifyEntry(ei);return;}}if(target.settings_section){settingDraft=structuredClone(state.settings);settingsSection=target.settings_section;page='Settings';settingsPage();toast('Review season dates. The statement has a transaction outside the current period; dates were not changed automatically.');return;}if(target.scheme){settingDraft=structuredClone(state.settings);const si=settingDraft.schemes.findIndex(s=>s.id===target.scheme);if(si>=0){schemeBuilder(si);return;}}if(target.late_ipt&&target.entry){lateIPTEditor(target.entry);return;}if(target.entry){const ei=record.entries.findIndex(e=>e.id===target.entry);if(ei>=0){const el=$('#voucher-'+ei);if(el){el.open=true;el.scrollIntoView?.({block:'center'});}const e=record.entries[ei];if(target.reparse)classifyEntry(ei);else if(e.classification_required||e.kind==='unknown')classifyEntry(ei);if(target.item_name){const ii=e.items.findIndex(i=>i.name===target.item_name);const row=$('#voucher-item-'+ei+'-'+ii);row?.scrollIntoView?.({block:'center'});toast('Review '+target.item_name+'. You can correct its mapping, classify the voucher as Sales Return/IPT, or delete an unwanted manual row.');}}}else if(target.item_name){const i=mappingGroups().findIndex(g=>g.name===target.item_name&&(!target.item_unit||g.unit===target.item_unit));if(i>=0)inlineMappingEditor(i);}if(target.step===2&&Number(result.unallocated)>0)toast(money(result.unallocated)+' remains unallocated. Split it to the correct crop/group before continuing.');}
async function paymentProceedAllowed(){if(record?.status!=='draft'||step!==2)return true;await calculate();if(Number(result.unallocated)<=0)return true;modal(`<h2>${money(result.unallocated)} still unallocated</h2><p>Allocate the remaining payment to a crop/group before continuing. Use Settlement for documented other-crop/prior-season money. All allocations must remain within the original receipt.</p><button id="back-to-payments" class="primary">Back to Assign Payments</button>`);return false;}
function entryField(idx,key,label,v,type='text'){return `<label>${label}<input type="${type}" data-entry="${idx}" data-key="${key}" value="${esc(v)}"></label>`}
function paymentTab(){return openingDuesPanel()+paymentStudioMetrics()+yearLinkRecordPanel()+openingCreditPanel()+`<details class="payment-source-review"><summary>Receipt sources & old dues · ${result.sources.length} source(s)</summary><div class="card"><h2>Starting balance and old dues</h2><p>Old dues remaining ${money(result.old_dues_remaining)}. Clearing dues here is allocation working; the receipt is already included once in the ledger.</p><div class="tablewrap"><table><tr><th>Receipt / opening source</th><th>Original date</th><th>Money received</th><th>Old dues cleared</th><th>Available afterwards</th><th>Still to allocate</th><th></th></tr>${result.sources.map(s=>`<tr><td>${esc(sourceLabel(s.id))}</td><td>${s.opening&&!s.date?'Opening credit (date not reconstructed)':date(s.date)+(s.opening?' · carried receipt':'')}</td><td>${money(s.amount)}</td><td>${money(s.old_dues_cleared)}</td><td>${money(s.available)}</td><td>${money(exactDifference(s.available,record.allocations.filter(a=>a.source===s.id).map(a=>a.amount||0)))}</td><td><button data-source="${esc(s.id)}" data-edit>Split this payment</button></td></tr>`).join('')}</table></div></div></details><div class="card"><h2>Payment & quantity allocation</h2><p>ABS and CD keep their existing rules. ABS remains product-wise. Excess ABS enters that segment’s first CD pool. Use Settlement for documented other-crop/prior-season money. Transfer unused CD by reducing its original assignment and assigning the same source to the destination.</p>${Number(result.unallocated)>0?`<div class="warn"><strong>${money(result.unallocated)} still unallocated.</strong> Allocate it to a crop/group or documented Settlement before continuing.</div>`:''}${chk('Use manual CD processing order','manual_order',record.manual_order)}<div class="actions"><button data-action="add-allocation" data-edit>Add allocation</button></div>${allocationStudio()}</div><details class="payment-detailed-working"><summary>Detailed benefit and payment working</summary>${paymentBenefitPanels()}</details>`}

let paymentSelectedId='',paymentBranchState=new Map();
function allocationTotal(rows){return exactDifference('0',[exactDifference('0',rows.map(a=>a.amount||'0'))]);}
function paymentStudioMetrics(){const available=exactDifference('0',[exactDifference('0',result.sources.map(s=>s.available||'0'))]);const allocated=allocationTotal(record.allocations);return `<div class="payment-metrics" aria-label="Payment allocation totals"><div class="glass-metric"><span class="metric-icon" aria-hidden="true">₹</span><label>Available after old dues<strong>${money(available)}</strong><small>Registered receipt / opening sources</small></label></div><div class="glass-metric"><span class="metric-icon" aria-hidden="true">↗</span><label>Allocated<strong>${money(allocated)}</strong><small>ABS, CD, Net Rate and Settlement</small></label></div><div class="glass-metric"><span class="metric-icon" aria-hidden="true">◷</span><label>Remaining<strong>${money(exactDifference(available,[allocated]))}</strong><small>Of the registered sources above</small></label></div></div><div class="${Number(result.old_dues_remaining)>0?'warn':'ok'} dues-strip">Old dues remaining <strong>${money(result.old_dues_remaining)}</strong><span>Original payment dates retained</span></div>`;}
function paymentBranchKey(parts){return JSON.stringify([activeWorkbook,record.id||record.party,...parts]);}
function paymentBranch(parts,title,body,hasSelected=false){const key=paymentBranchKey(parts);const open=hasSelected||paymentBranchState.get(key);return `<details class="allocation-branch branch-${parts.length}" data-payment-branch="${esc(key)}" ${open?'open':''}><summary>${title}</summary>${body}</details>`;}
let allocationFlow={scope:'',selection:null,type:'ABS',crop:'',scheme:''},allocationPanelWidth=350,allocationPanelCollapsed=false;
function flowSchemes(type){const cfg=calculationSettings(),allowed=allocationSchemes(type).filter(s=>(type!=='ABS'||s.benefits.includes('ABS'))&&(type!=='CD'||s.benefits.includes('CD')));return [...new Map([...allowed,...record.allocations.filter(a=>allocationViewType(a.type)===type).map(a=>cfg.schemes.find(s=>s.id===a.scheme)||{id:a.scheme||'',name:'Unresolved saved destination',crop:'Needs review',segment:'Needs review',products:[]})].map(s=>[s.id,s])).values()];}
function flowSegmentKey(s){return JSON.stringify([s.crop,s.crop==='Needs review'?s.id:s.segment_id||s.segment,s.packing_kg||'']);}
function flowGroups(schemes){const groups=new Map();for(const s of schemes){const key=flowSegmentKey(s);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);}return [...groups.values()];}
function cropGlyph(name){const wheat=/maize|bajra|paddy|wheat|rice/i.test(name);return `<svg viewBox="0 0 32 32" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${wheat?'<path d="M16 29V4M16 13C8 13 7 7 8 5c6 0 8 3 8 8ZM16 21C8 21 6 15 7 13c6 0 9 3 9 8ZM16 17c8 0 9-6 8-8-6 0-8 3-8 8ZM16 25c8 0 10-6 9-8-6 0-9 3-9 8Z"/>':'<path d="M16 29V16M8 21C0 16 5 7 11 10 10 2 22 2 21 10c7-3 12 7 4 11-2 5-7 6-9 2-3 4-7 3-8-2Z"/>'}</svg>`;}
function flowNode(id,title,sub,total,attrs,selected,icon=''){return `<button id="${id}" class="flow-node ${selected?'selected':''}" ${attrs} aria-pressed="${selected}">${icon?`<span class="flow-icon">${icon}</span>`:''}<strong>${esc(title)}</strong><small>${esc(sub)}</small><b>${money(total)}</b><span class="flow-check" aria-hidden="true">✓</span></button>`;}
function chooseAllocationFlow(type,crop,scheme){const schemes=flowSchemes(type);crop=crop&&schemes.some(s=>s.crop===crop)?crop:schemes[0]?.crop||'';const eligible=schemes.filter(s=>s.crop===crop);scheme=eligible.some(s=>s.id===scheme)?scheme:eligible.find(s=>Object.values(record.scheme_overrides||{}).includes(s.id))?.id||eligible[0]?.id||'';allocationFlow={scope:JSON.stringify([activeWorkbook,record.id||record.party]),type,crop,scheme,selection:''};paymentSelectedId=record.allocations.find(a=>(typeof paymentEntrySource!=='function'||!paymentEntrySource()||a.source===paymentEntrySource())&&allocationViewType(a.type)===type&&a.scheme===scheme)?.id||'';allocationFlow.selection=paymentSelectedId;render();}
function refreshAllocationFlow(){if(page!=='Calculate CN'||step!==2)return;setAllocationPanelWidth(allocationPanelWidth);drawAllocationFlow();}
function setAllocationPanelWidth(width){allocationPanelWidth=Math.max(280,Math.min(560,Math.round(width)));const studio=$('#connected-studio');if(studio?.style?.setProperty)studio.style.setProperty('--allocation-panel',allocationPanelWidth+'px');const label=$('#allocation-width-label');if(label)label.textContent=allocationPanelWidth+' px';const slider=$('#allocation-panel-width');if(slider)slider.value=allocationPanelWidth;const divider=$('#allocation-resizer');divider?.setAttribute?.('aria-valuenow',String(allocationPanelWidth));}
// Layout-only events never write to a calculation or settings object.
let allocationDragging=false;
document.addEventListener('input',e=>{if(e.target.id==='allocation-panel-width'){setAllocationPanelWidth(+e.target.value);globalThis.requestAnimationFrame?.(drawAllocationFlow);}});
document.addEventListener('pointerdown',e=>{radialPointerDown(e);if(e.target.id!=='allocation-resizer'||e.button!==0)return;allocationDragging=true;e.target.setPointerCapture?.(e.pointerId);document.body?.classList?.add('allocation-resizing');});
document.addEventListener('pointermove',e=>{radialPointerMove(e);if(!allocationDragging)return;const r=$('#connected-studio')?.getBoundingClientRect();if(r){setAllocationPanelWidth(r.right-e.clientX-7);globalThis.requestAnimationFrame?.(drawAllocationFlow);}});
function stopAllocationResize(){radialDrag=null;allocationDragging=false;document.body?.classList?.remove('allocation-resizing');}
document.addEventListener('pointerup',stopAllocationResize);document.addEventListener('pointercancel',stopAllocationResize);document.addEventListener('lostpointercapture',stopAllocationResize);
document.addEventListener('keydown',e=>{if(e.target.id!=='allocation-resizer'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();setAllocationPanelWidth(e.key==='Home'?280:e.key==='End'?560:allocationPanelWidth+(e.key==='ArrowLeft'?20:-20));globalThis.requestAnimationFrame?.(drawAllocationFlow);});
if(globalThis.ResizeObserver){const flowObserver=new ResizeObserver(()=>globalThis.requestAnimationFrame?.(drawAllocationFlow));const main=$('#main');if(main)flowObserver.observe(main);}
globalThis.addEventListener?.('resize',()=>globalThis.requestAnimationFrame?.(drawAllocationFlow));

let absDistribution=null;
async function openAbsDistribution(index=null,crop='',edits={}){
 if(record.status!=='draft')return;
 clearTimeout(saveTimer);await saveQueue;
 const a=index===null?null:record.allocations[index];if(index!==null&&a?.type!=='ABS'&&edits.type!=='ABS')throw Error('Choose an ABS allocation.');
 const seed={...a,...edits},candidateRecord=structuredClone(record);if(a)candidateRecord.allocations[index]=seed;const options=await api('/api/abs-distribution-preview',{record:candidateRecord,replace_id:a?.id||'',options:true});
 const selected=options.schemes.find(s=>s.id===seed.scheme);crop=crop||selected?.crop||([...new Set(options.schemes.map(s=>s.crop))].length===1?options.schemes[0].crop:'');
 const choices=options.schemes.filter(s=>s.crop===crop);const scheme=choices.some(s=>s.id===seed.scheme)?seed.scheme:choices.length===1?choices[0].id:'';
 absDistribution={snapshot:JSON.stringify(record),workbook:activeWorkbook,record:candidateRecord,options,plan:null,draft:{replace_id:a?.id||'',crop,scheme,source:seed.source||(typeof paymentEntrySource==='function'?paymentEntrySource():''),amount:Number(seed.amount)>0?seed.amount:'',approved:!!seed.approved,remark:seed.remark||''}};
 if(!absDistribution.draft.source){const sources=options.sources.filter(s=>Number(s.remaining)>0&&(!scheme||s.eligible_schemes.includes(scheme)));if(sources.length===1)absDistribution.draft.source=sources[0].id;}
 absDistributionForm();
}
function absDistributionForm(){const d=absDistribution;if(!d)return;const v=d.draft,crops=[...new Set(d.options.schemes.map(s=>s.crop))],schemes=d.options.schemes.filter(s=>s.crop===v.crop),p=d.plan;
 modal(`<h2>Automatic ABS distribution</h2><p>Select the crop. A single eligible segment is selected automatically; multiple segments require your choice. The amount is split across eligible net-sold products. You can edit every saved split afterwards.</p><div class="grid two"><label>Crop<select id="absd-crop">${option('','Choose crop',v.crop)}${crops.map(c=>option(c,c,v.crop)).join('')}</select></label><label>Segment / scheme<select id="absd-scheme">${option('','Choose segment / scheme',v.scheme)}${schemes.map(s=>option(s.id,s.segment+' · '+s.name,v.scheme)).join('')}</select></label><label>Money received<select id="absd-source">${option('','Choose receipt / opening credit',v.source)}${d.options.sources.map(s=>option(s.id,sourceLabel(s.id)+' · '+(s.date?date(s.date):'Undated opening credit')+' · '+money(s.remaining)+' available',v.source).replace('<option ',v.scheme&&!s.eligible_schemes.includes(v.scheme)?'<option disabled ':'<option ')).join('')}</select></label><label>Amount to distribute (₹)<input id="absd-amount" type="number" min="0" step="any" value="${esc(v.amount)}"></label></div><details ${v.approved||v.remark?'open':''}><summary>Extension approval / note</summary><label class="check"><input id="absd-approved" type="checkbox" ${v.approved?'checked':''}>Extended ABS approved</label><label>Remark<input id="absd-remark" value="${esc(v.remark)}"></label></details><p>Only payments within this scheme’s original-date booking rules are eligible. No source dates or ledger entries change.</p><p id="absd-preview-status"></p>${p?`<div class="ok"><strong>${esc(p.scheme_name)}</strong> · Total split ${money(p.amount)} · ${p.original_date?date(p.original_date):'Undated opening credit'}</div><div class="tablewrap"><table><tr><th>Product</th><th>Regular net sold</th><th>Remaining token requirement</th><th>Proposed ABS split</th></tr>${p.products.map(x=>`<tr><td>${esc(x.product)}</td><td>${esc(x.net_sold)} ${esc(x.unit)}</td><td>${money(x.remaining_token_capacity)}</td><td>${money(x.amount)}<br><small>Token ${money(x.token_applied)} · Excess ${money(x.excess)}</small></td></tr>`).join('')}</table></div><p>${esc(p.basis)}</p><p><strong>Scheme totals after this split:</strong> ABS CN ${money(p.ABS_CN)} · Excess ABS ${money(p.excess_ABS)} · CD CN ${money(p.CD_CN)}. These include existing allocations; CD remains capped by the scheme balance.</p>${p.issues.length?`<div class="warn"><strong>Draft still needs review; these issues are not resolved by allocation:</strong><ul>${p.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}`:''}<div class="actions"><button id="absd-preview" class="primary">Preview distribution</button>${p?'<button id="absd-apply" class="primary">Apply split to draft</button>':''}<button id="absd-cancel">Cancel</button></div>`);
}
function readAbsDistributionForm(){if(!absDistribution)return;const v=absDistribution.draft;for(const key of ['crop','scheme','source','amount','remark']){const t=$('#absd-'+key);if(t)v[key]=t.value;}v.approved=!!$('#absd-approved')?.checked;}
async function previewAbsDistribution(){const d=absDistribution;if(!d)return;readAbsDistributionForm();if(!d.draft.scheme)throw Error('Choose a segment/scheme before previewing the split.');const inputs=JSON.stringify(d.draft);d.plan=null;const plan=await api('/api/abs-distribution-preview',{record:d.record,...d.draft});if(absDistribution!==d)return;if(JSON.stringify(d.draft)!==inputs)throw Error('Inputs changed while previewing. Preview the split again.');d.plan=plan;d.previewInputs=inputs;absDistributionForm();}
async function applyAbsDistribution(){const d=absDistribution;if(!d?.plan)return;if(d.workbook!==activeWorkbook||JSON.stringify(record)!==d.snapshot)throw Error('Calculation changed; open a fresh ABS distribution preview.');
 readAbsDistributionForm();if(JSON.stringify(d.draft)!==d.previewInputs){d.plan=null;throw Error('Inputs changed — preview the split again before applying.');}
 const saved=await api('/api/abs-distribution-apply',{record:d.record,...d.draft,settings_version:d.plan.settings_version});record=saved;paymentSelectedId=d.draft.replace_id||record.allocations.at(-1)?.id||'';absDistribution=null;$('#modal').close();await refresh();await calculate();render();toast('ABS split saved. Each product allocation can be edited manually.');}

async function addDestinationAllocation(scheme,type,product=''){if(record.status!=='draft')return;const sc=allocationSchemes(type).find(s=>s.id===scheme);if(!sc||type==='ABS'&&!sc.benefits.includes('ABS'))throw Error('Review net sales and scheme availability first.');if(!result.sources.length)throw Error('Add a receipt or register available opening credit first.');const eligible=result.sources.filter(s=>type!=='ABS'||absSourceAllowed(s,sc));const preferred=typeof paymentEntrySource==='function'?paymentEntrySource():'';if(preferred&&!eligible.some(s=>s.id===preferred))throw Error('The selected payment is not eligible for this ABS booking period. Select another payment explicitly.');const source=eligible.find(s=>s.id===preferred)||eligible.find(s=>Number(exactDifference(s.available,record.allocations.filter(a=>a.source===s.id).map(a=>a.amount||'0')))>0)||eligible[0];if(!source)throw Error('No receipt is eligible for this scheme’s ABS booking period. July payments outside that period must use CD / Settlement.');if(type!=='Settlement'){const base=baseForScheme(sc);if(base)setSegmentScheme(base.id,sc.id);}const a={id:uid(),source:source.id,type,scheme:sc.id,product,amount:'0',remark:''};record.allocations.push(a);paymentSelectedId=a.id;changed();await calculate();render();}
document.addEventListener('toggle',e=>{const key=e.target.dataset?.paymentBranch;if(key)paymentBranchState.set(key,e.target.open);},true);

function exactDifference(first,rest){const parts=[decimalParts(first),...rest.map(decimalParts)],scale=Math.max(...parts.map(p=>p.scale));let n=parts[0].n*10n**BigInt(scale-parts[0].scale);for(const p of parts.slice(1))n-=p.n*10n**BigInt(scale-p.scale);const sign=n<0n?'-':'';let digits=(n<0n?-n:n).toString().padStart(scale+1,'0');return sign+(scale?digits.slice(0,-scale)+'.'+digits.slice(-scale):digits);}
function openingCreditAvailable(){const opening=decimalParts(record.opening||0);return opening.n<0n?exactDifference(String(record.opening).replace(/^-/,''),record.opening_sources.map(s=>s.amount||0)):'0';}
function sourceLabel(id){const s=result.sources.find(s=>s.id===id);if(s?.opening)return record.opening_sources.find(x=>x.id===id)?.label||'Opening credit';const e=record.entries.find(e=>e.id===id);return e?.reference||id;}
function openingCreditPanel(){if(Number(record.opening)>=0)return '';const cap=-Number(record.opening),registered=record.opening_sources.reduce((n,s)=>n+Number(s.amount||0),0),used=record.allocations.filter(a=>record.opening_sources.some(s=>s.id===a.source)).reduce((n,a)=>n+Number(a.amount||0),0);return `<div class="card"><h2>Already credited amount</h2><p>Opening credit <strong>${money(cap)}</strong> · Allocated <strong>${money(used)}</strong> · Still available <strong>${money(Math.max(0,cap-used))}</strong></p><p>Allocate this credit to ABS, or choose CD / Settlement when appropriate. Every split shares the same credit limit. This does not add a new receipt or change the ledger balance. Undated opening credit receives 0% direct CD; excess ABS follows the selected scheme’s first CD slab.</p>${cap-used>0?`<button data-action="opening-source" data-edit class="primary">Allocate available opening credit</button>`:'<div class="ok">Opening credit fully allocated — ₹0 left to allocate.</div>'}${registered<cap?`<p>${money(cap-registered)} not yet added to allocation sources.</p>`:''}</div>`;}
async function allocateOpeningCredit(){if(record.status!=='draft')return;const remaining=openingCreditAvailable();let source;if(Number(remaining)>0){source={id:uid(),amount:remaining,date:null};await api('/api/validate-limits',{...record,opening_sources:[...record.opening_sources,source]});record.opening_sources.push(source);}else source=record.opening_sources.find(s=>Number(exactDifference(s.amount,record.allocations.filter(a=>a.source===s.id).map(a=>a.amount||0)))>0);if(!source){toast('Opening credit is fully allocated. Reduce an existing split to reallocate.');return;}record.allocations.push({id:uid(),source:source.id,type:'ABS',scheme:defaultAllocationScheme('ABS'),product:'',amount:'0',remark:''});paymentSelectedId=record.allocations.at(-1)?.id||'';changed();await calculate();render();}
function slabLabel(w){if(!w.slab&&Number(w.percent)>0)return 'Stored CD rate · '+esc(w.percent)+'%';return w.slab?`CD slab ${w.slab}: ${date(w.period.start)} to ${date(w.period.end)} · ${esc(w.percent)}%`:'No applicable CD slab · 0%';}
function allocationPreview(a){if(a.type==='Net'){const cn=result.CNs.find(c=>c.scheme===a.scheme&&c.benefit==='Net rate');return '<p>Net Rate payment assignment · no additional ABS or CD. The scheme CN is based on eligible net sold quantity.</p>'+(cn?'<p>Net Rate scheme CN '+money(cn.rounded)+' (scheme total, not additional per payment).</p>':'');}const g=result.groups?.find(g=>g.scheme===a.scheme);if(a.type==='Settlement')return '<p>Settlement · no new CN from this allocation.</p>';if(!g)return '<p>Complete the scheme and product review to see benefit working.</p>';if(a.type==='CD'){const w=g.CD_work.find(w=>w.allocation===a.id);return w?`<strong>${slabLabel(w)}</strong><p>Eligible payment ${money(w.eligible_payment)} × ${esc(w.percent)}% = ${money(w.CD)} precise CN.</p><small>${money(w.unused)} unused for CD. Payment + CN is capped at the scheme balance.</small>`:'<p>Allocation needs review before a benefit can be shown.</p>';}if(a.type==='ABS'){const cn=result.CNs.find(c=>c.scheme===a.scheme&&c.benefit==='ABS'),w=cn?.working?.find(w=>w.product_id===a.product);return w?`<strong>ABS rate ${money(w.CN_rate)} / ${esc(w.unit)}</strong><p>${esc(w.eligible)} eligible ${esc(w.unit)} × ${money(w.CN_rate)} = ${money(w.CN)} precise CN.</p><small>Combined ABS for this product across all its splits. ${money(w.excess)} excess enters this scheme’s first CD slab.</small>`:'<p>Choose an eligible product and amount to see ABS benefit.</p>';}const p=calculationSettings().products.find(p=>p.id===a.product);const cn=result.CNs.find(c=>c.scheme===a.scheme&&c.benefit==='Cash '+p?.name);return '<p>Cash benefit uses the reviewed cash supplied/returned split.</p>'+(cn?`<p>Scheme Cash CN ${money(cn.rounded)} (combined, rounded separately).</p>`:'');}
function paymentBenefitPanels(){const cfg=calculationSettings();return (result.groups||[]).map(g=>{const sc=cfg.schemes.find(s=>s.id===g.scheme),cns=result.CNs.filter(c=>c.scheme===g.scheme||(c.scheme===undefined&&c.crop===g.crop&&c.segment===g.segment)),abs=cns.find(c=>c.benefit==='ABS');return `<div class="card"><h2>${esc(sc?.name||g.segment)}</h2><p>${esc(g.crop)} / ${esc(g.segment)} · Net sold ${esc(g.net)} ${esc(g.unit)}</p><div class="tablewrap"><table><tr><th>Benefit</th><th>Qualifying slab / rule</th><th>Separate rounded CN</th></tr>${cns.map(c=>`<tr><td>${esc(benefitNames[c.benefit]||c.benefit)}</td><td>${benefitRule(c,sc,g)}</td><td>${money(c.rounded)}</td></tr>`).join('')}</table></div>${abs?.working?.length?`<h3>ABS booking benefit</h3><table><tr><th>Product</th><th>Allocated token</th><th>Eligible net sold</th><th>CN rate</th><th>Precise CN</th><th>Excess to first CD slab</th></tr>${abs.working.map(w=>`<tr><td>${esc(w.product)}</td><td>${money(w.allocated)}</td><td>${esc(w.eligible)} ${esc(w.unit)}</td><td>${money(w.CN_rate)} / ${esc(w.unit)}</td><td>${money(w.CN)}</td><td>${money(w.excess)}</td></tr>`).join('')}</table>`:''}${g.CD_work.length?`<h3>Payment discount by allocation</h3><div class="tablewrap"><table><tr><th>Payment / original date</th><th>Applicable CD slab</th><th>Allocated</th><th>Eligible payment</th><th>Precise CN</th><th>Unused for CD</th></tr>${g.CD_work.map(w=>`<tr><td>${w.source?esc(sourceLabel(w.source))+' · '+(w.original_date?date(w.original_date):'Undated opening credit'):'Excess ABS — first CD slab'}</td><td>${slabLabel(w)}</td><td>${money(w.assigned)}</td><td>${money(w.eligible_payment)}</td><td>${money(w.CD)}</td><td>${money(w.unused)}</td></tr>`).join('')}</table></div><p>CD rows keep full precision. Their combined CN is rounded once for this scheme. Unused for CD remains assigned to this scheme; reduce its split before moving it elsewhere.</p>`:''}<p>Quantity, trip and return benefits depend on net sales and scheme rules. Payment allocation determines ABS / CD eligibility.</p></div>`;}).join('');}
function benefitRule(c,sc,g){const w=c.working||{},t=w.tier;let label=t?`${t.inclusive?'From':'Above'} ${esc(t.above)}${t.upto!=null?' to '+esc(t.upto):' and above'} ${esc(g.unit)}${t.name?' · '+esc(t.name):''}`:'No qualifying slab';if(c.benefit==='Quantity')return sc.quantity_mode==='progressive'?`Progressive slabs on ${esc(g.net)} ${esc(g.unit)}:<br>${sc.quantity.map(t=>`Above ${esc(t.above)}${t.upto!=null?' to '+esc(t.upto):' and above'} ${esc(g.unit)} · ${money(t.rate)} / ${esc(g.unit)}`).join('<br>')}<br>Above the final limit, its rate continues.`:label+(t?` · ${money(t.rate)} / ${esc(g.unit)}`:'');if(c.benefit==='Extra')return label+(t?` · ${money(t.rate)}${sc.extra_unit==='fixed'?' total':' / '+esc(sc.extra_unit)}`:'');if(c.benefit==='ABS')return `Eligible net sales / token booking · ${money(sc.abs_rate)} / ${esc(sc.abs_unit)}`;if(c.benefit==='CD')return 'Original-date CD slabs shown below; excess ABS uses first slab.';if(c.benefit==='Return')return `${w.qualifies?'Qualified':'Not qualified'} · Returns ${w.return_percent==null?'no supply':Number(w.return_percent).toFixed(2)+'%'}; limit ${esc(w.threshold)}% · ${money(sc.return_rate)} / ${esc(sc.return_unit)}`;if(c.benefit==='Net rate')return w.mode==='fixed_CN'?`${esc(w.net_quantity)} ${esc(w.unit)} × ${money(w.CN_per_unit)}`:label+(t?` · Net price ${money(t.rate)} / ${esc(g.unit)}`:'');return 'Reviewed cash split and return deduction';}
function cashSplitChoices(){const cfg=calculationSettings(),sold=soldProductIds();return allocationSchemes('Cash').flatMap(s=>cfg.products.filter(p=>s.products.includes(p.id)&&sold.has(p.id)&&!p.deleted_at&&s.cash?.products.includes(p.name)&&!record.cash_splits.some(c=>c.scheme===s.id&&c.product===p.id)).map(p=>({scheme:s.id,product:p.id,label:p.name+' · '+s.name+' · '+s.unit})));}
function addCashSplit(){const choices=cashSplitChoices();if(!choices.length){toast('All eligible cash products already have a split, or no eligible cash product was sold.');return;}if(choices.length===1){commitCashSplit(choices[0].scheme,choices[0].product);return;}modal(`<h2>Choose Cash product and scheme</h2><p>Enter supplied/returned quantities separately for each selected product.</p>${choices.map(c=>`<button data-cash-choice="${esc(c.product)}" data-cash-scheme="${esc(c.scheme)}">${esc(c.label)}</button>`).join('')}`);}
function commitCashSplit(scheme,product){if(record.status!=='draft')return;if(!cashSplitChoices().some(c=>c.scheme===scheme&&c.product===product))throw Error('Cash choice changed; reopen the product selector.');record.cash_splits.push({scheme,product,supplied:'0',returned:'0',deduction_rate:null,remark:''});changed();render();}
function cashField(i,k,l,v,t='number'){return `<label>${l}<input type="${t}" data-cash="${i}" data-key="${k}" value="${esc(v)}"></label>`}
function allocationRow(a,i){const cfg=calculationSettings();const sc=cfg.schemes.find(s=>s.id===a.scheme);const needsProduct=['ABS','Cash','Net'].includes(a.type);const choices=allocationSchemes(a.type);const names=option('','Choose a scheme',a.scheme)+(!choices.some(s=>s.id===a.scheme)&&sc?option(sc.id,sc.name+(sc.deleted_at?' — deleted scheme; restore or choose another':' — saved choice needs review (no net sales / different season)'),a.scheme):'')+choices.map(s=>option(s.id,s.name+' — '+s.crop+' / '+s.segment,a.scheme)).join('');const sold=soldProductIds();const members=cfg.products.filter(p=>sc?.products.includes(p.id)&&sold.has(p.id));return `<tr><td><label>Money received<select data-allocation="${i}" data-key="source">${!result.sources.some(s=>s.id===a.source)?option(a.source||'','Saved source missing — choose a payment',a.source||''):''}${result.sources.map(s=>{const blocked=a.type==='ABS'&&!absSourceAllowed(s,sc);return option(s.id,sourceLabel(s.id)+' · '+(s.opening?'Opening credit':date(s.date))+' · '+money(s.amount)+(blocked?' · Not eligible for ABS':''),a.source).replace('<option ',blocked?'<option disabled ':'<option ');}).join('')}</select></label><label>Allocation type<select data-allocation="${i}" data-key="type">${['ABS','CD','Net','Cash','Settlement'].map(k=>option(k,k==='Net'?'Net Rate':k==='Cash'?'Net Rate · Cash quantity booking':k,a.type)).join('')}</select></label></td><td><label>Scheme name<select data-allocation="${i}" data-key="scheme">${names}</select></label>${needsProduct?`<label>Product for ${a.type}<select data-allocation="${i}" data-key="product">${option('',a.type==='ABS'?'All eligible products — automatic split':'Choose a product',a.product)}${a.product&&!members.some(p=>p.id===a.product)?option(a.product,'Saved product needs review (no net sales)',a.product):''}${members.map(p=>option(p.id,p.name+' · '+p.packing_kg+' kg',a.product)).join('')}</select></label>${a.type==='ABS'?`<button data-abs-distribute="${i}" data-edit>Preview automatic product split</button><small>Blank product uses a reviewed automatic split. Choose a product above for a manual allocation.</small>`:''}`:'<p class="muted">Product is not needed for this allocation.</p>'}</td><td><label>Amount to allocate (₹)<input type="number" step="any" min="0" max="${allocationRemaining(a,i)}" data-allocation="${i}" data-key="amount" value="${esc(a.amount)}"></label>${absAllocationError(a)?`<p class="warn">${esc(absAllocationError(a))} Saved split retained; change its type/source or remove it.</p>`:''}<small>Maximum for this row: ${money(allocationRemaining(a,i))}. All splits share the same payment.</small>${record.manual_order?`<label>CD processing order (1, 2, 3…)<input type="number" min="0" step="1" data-allocation="${i}" data-key="order" value="${esc(a.order||0)}"></label>`:'<small>Processed by original receipt date.</small>'}</td><td>${allocationPreview(a)}</td><td>${a.type==='ABS'?`<label class="check"><input type="checkbox" data-allocation="${i}" data-key="approved" ${a.approved?'checked':''}>Extended ABS approved</label>`:''}<label>Remark<input data-allocation="${i}" data-key="remark" value="${esc(a.remark)}" placeholder="Optional allocation note"></label></td><td><button data-remove-allocation="${i}" data-edit>Remove</button></td></tr>`}
function setSegmentScheme(baseId,schemeId){let previous=record.scheme_overrides?.[baseId]||baseId;for(const a of record.allocations)if(a.scheme===previous||a.scheme===baseId){const error=absAllocationError({...a,scheme:schemeId});if(error)throw Error(error);}record.scheme_overrides=record.scheme_overrides||{};record.scheme_overrides[baseId]=schemeId;for(let a of record.allocations)if(a.scheme===previous||a.scheme===baseId)a.scheme=schemeId;for(let c of record.cash_splits)if(c.scheme===previous||c.scheme===baseId)c.scheme=schemeId;}
function baseForScheme(sc){return baseSegments().find(base=>base.crop===sc.crop&&(base.segment_id&&sc.segment_id?base.segment_id===sc.segment_id:base.segment===sc.segment))}
function benefitTab(){return stockSummary()+simpleSchemeCards()+(result.groups.map(g=>`<div class="card"><h2>${esc(g.crop)} / ${esc(g.segment)}</h2><p>Invoice supply ${g.invoice_supplied??g.supplied} · IPT received ${g.ipt_received||0} · IPT given ${g.ipt_given||0} · Adjusted supply ${g.stock_adjusted_supply??g.supplied} · Actual returned ${g.stock_actual_returned??g.returned} · ${Number(g.stock_adjusted_supply??g.supplied)!==Number(g.supplied)?'Regular net after Cash split':'Net'} ${g.net} ${g.unit}</p><p>Segment balance ${money(g.segment_balance)} · Used ABS principal ${money(g.used_token_principal)} · Allocated excess ABS ${money(g.excess_ABS)}</p>${result.CNs.filter(c=>c.crop===g.crop&&c.segment===g.segment).map(c=>`<div class="benefit"><strong>${esc(c.benefit)}</strong> ${money(c.rounded)}${Number(c.rounded)===0?' · Zero: no CN issued':''}<details><summary>Show calculation</summary><p>Precise ${esc(c.precise)} · Rounding ${esc(c.rounding)}</p><pre>${esc(JSON.stringify(c.working,null,2))}</pre></details></div>`).join('')}<details><summary>View frozen/applicable settings</summary><pre>${esc(JSON.stringify((record.frozen_settings||state.settings).schemes.find(s=>s.id===g.scheme),null,2))}</pre></details></div>`).join('')||'<div class="card">Enter or import products to check benefits.</div>')}
function finishTab(){return productCNReview()+stockSummary()+`<div class="card finish-review"><span class="eyebrow">05 / FINAL REVIEW</span><h2>Review & Finish</h2>${result.issues.length?`<div class="warn"><strong>Needs correction — finalisation blocked</strong><ul>${result.issues.map((message,index)=>`<li><button data-review-issue="${index}">${esc(message)} → Review</button></li>`).join('')}</ul></div>`:'<div class="ok">Ready to finish — reconciliation and prerequisites passed.</div>'}<details><summary>Separate benefit CN / narration and proposed issue amounts</summary><div class="tablewrap"><table><tr><th>Separate CN / narration</th><th>Precise entitlement</th><th>Rounding</th><th>Previously issued</th><th>Proposed new CN</th></tr>${result.CNs.map(c=>`<tr><td>${esc(c.narration)}</td><td>${money(c.precise)}</td><td>${money(c.rounding)}</td><td>${money(c.previous_issued)}</td><td>${money(c.proposed)}</td></tr>`).join('')}</table></div></details><p>Ledger ${money(result.ledger_closing)} − proposed CN ${money(result.new_CN_total)} = final balance ${money(result.final_balance)}</p><div class="actions finish-actions"><button class="primary" data-action="finalise" ${!result.can_finalise||record.status!=='draft'?'disabled':''}>Finish Calculation</button><button data-action="issue" ${record.status!=='finalised'?'disabled':''}>Mark CNs as Issued</button><button data-action="revise" ${record.status==='draft'?'disabled':''}>Create Revised Version</button><button data-action="print">Print Summary</button><button data-action="print-detail">Print Detailed Working</button><button id="export-product-csv">Export Product Summary (CSV)</button><button data-shared-action="export">Share Editable Project</button><button data-action="export">Export Summary & Separate CN Details (JSON)</button></div><details><summary>Information (does not block alone)</summary><pre>${esc(result.information.join('\n')||'None')}</pre></details></div>`}
let settingsSection='schemes',schemeCropFilter='All',showDeletedSchemes=false;
function settingsPage(){if(['sharing','storage'].includes(settingsSection))return sharedSettingsPage();settingDraft=settingDraft||structuredClone(state.settings);$('#main').innerHTML=`${pageHead('Settings · '+state.workbook.name,'Manage this workbook’s schemes, periods, products and backups.','CONFIGURATION')}<p><strong>My Schemes and products belong only to ${esc(state.workbook.name)}.</strong> Switch workbooks in the sidebar to view another setup. Deleting a scheme does not remove calculation rules.</p><p>Choose a section. You do not need to change settings for every party.</p><div class="tabs">${[['schemes','My Schemes'],['seasons','Working Periods'],['products','Products & Packing'],['backup','Backup & Restore'],['sharing','Share & Open Work'],['storage','Storage & Delete']].map(([k,l])=>`<button data-settings-section="${k}" class="${settingsSection===k?'active':''}">${l}</button>`).join('')}</div>${settingsSection==='schemes'?`<div class="actions"><button data-action="builder" class="primary">Create New Scheme</button><button data-action="add-crop">Add New Crop</button><button id="toggle-deleted-schemes">${showDeletedSchemes?'Show Active Schemes':'Deleted Schemes'}</button><label>Select saved scheme<select id="saved-scheme">${option('','Select to edit','')}${settingDraft.schemes.map((s,i)=>({s,i})).filter(({s})=>!s.deleted_at&&!s.mapping_placeholder&&(schemeCropFilter==='All'||s.crop===schemeCropFilter)).map(({s,i})=>option(String(i),s.name+' — '+s.crop+' / '+s.segment,'')).join('')}</select></label><label>Crop<select id="scheme-crop-filter">${['All',...catalogCrops()].map(c=>option(c,c,schemeCropFilter)).join('')}</select></label></div><div class="grid two">${settingDraft.schemes.map((s,i)=>({s,i})).filter(({s})=>!s.mapping_placeholder&&Boolean(s.deleted_at)===showDeletedSchemes&&(schemeCropFilter==='All'||s.crop===schemeCropFilter)).map(({s,i})=>`<div class="card settings-scheme-card"><span class="pill">${esc(s.crop+' / '+s.segment)}</span><h2>${esc(s.name)}</h2><p>${esc(s.season)} · ${esc(s.states.join(', ')||'States not entered')}</p><p>${s.benefits.map(b=>esc(benefitNames[b]||b)).join(' + ')}</p><p>${s.confirmed?'Confirmed setup':'Draft — finish dates, states and confirmation before use'}</p>${s.deleted_at?`<p>Deleted · recoverable</p><button data-restore-scheme="${esc(s.id)}">Restore Scheme</button><button data-purge-kind="scheme" data-purge-id="${esc(s.id)}">Permanently Delete…</button>`:`<button data-scheme="${i}" class="primary">Edit Rates & Slabs</button><button data-delete-scheme="${esc(s.id)}">Delete Scheme</button>`}</div>`).join('')}</div>`:settingsSection==='seasons'?`<div class="card seasons-card"><span class="eyebrow">SALES & BENEFIT PERIODS</span><h2>Season / working-period dates</h2><p>For workbook calculations, stock outside the selected period stays in the full-year ledger and receives no benefit in this calculation. Earlier ABS receipts keep their original dates.</p><p>Missing dates stay blank. Enter and confirm them before finishing a calculation.</p>${settingDraft.seasons.map((s,i)=>`<div class="grid">${seasonField(i,'name','Season name',s.name)}${seasonField(i,'start','Sales / return start',s.start,'date')}${seasonField(i,'end','Sales / return end',s.end,'date')}${seasonField(i,'cutoff','Calculation cutoff',s.cutoff,'date')}<label class="check"><input type="checkbox" data-season="${i}" data-key="confirmed" ${s.confirmed?'checked':''}>These season dates are correct</label></div>`).join('')}<div class="actions"><button data-action="save-settings" class="primary">Save Season Dates</button><button data-action="copy-season">Copy Previous Season</button></div></div>`:settingsSection==='products'?`<div class="card catalogue-card"><span class="eyebrow">WORKBOOK CATALOGUE</span><h2>Products & Packing</h2><p>DAWAT 1 kg and 3 kg remain separate. Aliases match names found in your ledger.</p><div class="tablewrap"><table><tr><th>Crop</th><th>Segment</th><th>Product</th><th>Packing</th><th>Other ledger names (comma-separated)</th><th></th></tr>${settingDraft.products.map((p,i)=>`<tr><td>${esc(p.crop)}</td><td>${esc(p.segment)}</td><td>${esc(p.name)}</td><td>${esc(p.packing_kg)} kg</td><td><input data-alias="${i}" value="${esc(p.aliases.join(', '))}"></td><td><button data-edit-product="${i}" ${p.deleted_at?'disabled':''}>Edit Product</button><button data-product-delete="${esc(p.id)}" data-restore="${p.deleted_at?'yes':'no'}">${p.deleted_at?'Restore Product':'Delete Product'}</button>${p.deleted_at?'<small>Archived; historical mappings retained</small>':''}</td></tr>`).join('')}</table></div><div class="actions"><button data-action="add-crop" class="primary">Add New Crop</button><button data-action="add-group">Add Segment / Packing Group</button><button data-action="add-product">Add New Product</button><button data-action="save-settings">Save Ledger Names</button></div><p>Add New Crop creates its first packing group, product and scheme draft. Add Segment / Packing Group creates another group under an existing crop. Edit a product’s name or ledger aliases. For a different packing or group, add a separate product to keep saved calculations safe.</p></div>`:`<div class="card backup-card"><span class="eyebrow">PROTECT YOUR WORK</span><h2>Backup & Restore</h2><p>Download a backup of all workbooks in the selected project, existing calculations, schemes and import-review queues. Other projects are separate. To open someone else’s work, use Share & Open Work. Restore previews what will be replaced and makes a safety copy first.</p><button data-action="backup">Download Backup</button><label>Choose backup to restore<input id="restore" type="file" accept="application/json"></label></div>`}`}
function catalogCrops(){const cfg=settingDraft||state.settings;return [...new Set([...(cfg.crops||[]),...cfg.schemes.map(s=>s.crop),...cfg.products.map(p=>p.crop)].filter(Boolean))];}
let addingNewCrop=true;
function cropGroupEditor(newCrop=true){addingNewCrop=newCrop;const crop=catalogCrops()[0]||'';modal(`<h2>${newCrop?'Add New Crop':'Add Segment / Packing Group'}</h2><p>1. Name the crop/group and packing. 2. Add the first product. 3. Set benefit rates in its scheme.</p><div class="grid two">${newCrop?'<label>New crop name<input id="cg-crop-name" placeholder="For example: Wheat or Soybean"></label>':`<label>Crop<select id="cg-crop">${catalogCrops().map(c=>option(c,c,crop)).join('')}</select></label>`}<label>Segment / packing group name<input id="cg-group" placeholder="For example: Research Wheat or 30 kg packs"></label><label>Packing weight (kg per packet)<input id="cg-packing" type="number" min="0.000001" step="any" placeholder="For example: 30"></label><label>Calculate quantities in<select id="cg-unit">${option('kg','Kilograms (kg)','kg')}${option('packet','Packets','kg')}</select></label><label>First product name<input id="cg-product" placeholder="Enter one product; you can add more later"></label><label>Other ledger names (comma-separated, optional)<input id="cg-aliases"></label><label>Scheme name<input id="cg-scheme-name" placeholder="For example: Wheat 2026 Scheme"></label><label>Season<select id="cg-season">${settingDraft.seasons.map(x=>option(x.name,x.name,record?.season||settingDraft.seasons[0]?.name)).join('')}</select></label></div><p>Rates start blank. No benefits from another crop are copied. After saving, choose benefits and enter your actual rates and dates.</p><button id="save-crop-group" class="primary">Save & Set Up Scheme</button>`);}
function newGroupDraft(input,cfg){const crop=input.crop.trim(),segment=input.segment.trim(),product=input.product.trim(),name=input.name.trim(),packing=input.packing.trim();if(!crop||!segment||!product||!name)throw Error('Enter the crop, group, first product and scheme names.');if(crop.toLowerCase()==='all')throw Error('Use a crop name other than All.');const crops=[...new Set([...cfg.schemes.map(s=>s.crop),...cfg.products.map(p=>p.crop)])];if(input.newCrop&&crops.some(c=>c.toLowerCase()===crop.toLowerCase()))throw Error('This crop already exists. Use Add Segment / Packing Group.');if(!input.newCrop&&!crops.includes(crop))throw Error('Choose an existing crop.');if(!Number.isFinite(Number(packing))||Number(packing)<=0)throw Error('Enter a positive packing weight in kg.');if(!['kg','packet'].includes(input.unit))throw Error('Choose kg or packets.');if(!cfg.seasons.some(s=>s.name===input.season))throw Error('Choose an existing season.');if(cfg.schemes.some(s=>s.crop.toLowerCase()===crop.toLowerCase()&&s.segment.toLowerCase()===segment.toLowerCase()))throw Error('This group name already exists for the crop. Use a different group name for separate packing.');const sid=uid(),pid=uid(),segmentId=uid();const scheme={id:sid,segment_id:segmentId,version:1,name,crop,segment,season:input.season,states:[],confirmed:false,unit:input.unit,packing_kg:packing,billing:null,billing_unit:input.unit,benefits:[],quantity_mode:'whole',quantity:[],extra:[],extra_unit:'fixed',token:null,abs_rate:null,abs_unit:input.unit,abs_start:null,abs_end:null,extended_end:null,cd:[],return_threshold:'0',return_rate:null,return_unit:input.unit,net:[],cash:null,products:[pid],narration:'{party} | {crop} | {segment} | {season} | {benefit}',remark:'New crop/group: enter and confirm your own rates, dates and states.'};const item={id:pid,segment_id:segmentId,name:product,crop,segment,packing_kg:packing,scheme:sid,aliases:input.aliases.split(',').map(x=>x.trim()).filter(Boolean)};return {scheme,product:item};}
async function saveCropGroup(){const data=newGroupDraft({crop:addingNewCrop?$('#cg-crop-name').value:$('#cg-crop').value,segment:$('#cg-group').value,packing:$('#cg-packing').value,unit:$('#cg-unit').value,product:$('#cg-product').value,aliases:$('#cg-aliases').value,name:$('#cg-scheme-name').value,season:$('#cg-season').value,newCrop:addingNewCrop},settingDraft);const draft=structuredClone(settingDraft);draft.products.push(data.product);draft.schemes.push(data.scheme);settingDraft=await api('/api/settings',draft);await refresh();$('#modal').close();settingsSection='schemes';schemeCropFilter=data.scheme.crop;settingsPage();schemeBuilder(settingDraft.schemes.findIndex(s=>s.id===data.scheme.id));toast('Crop/group and first product saved. Choose benefits and enter rates in this scheme.');}
let productEditing=null;
function productEditor(index=null){productEditing=index;const p=index===null?null:settingDraft.products[index];const group=p?settingDraft.schemes.find(s=>s.id===p.scheme):settingDraft.schemes[0];modal(`<h2>${p?'Edit Product':'Add New Product'}</h2><p>Choose the crop / packing group, then enter the product name. Packing comes from the group.</p><div class="grid two"><label>Crop / packing group<select id="product-group" ${p?'disabled':''}>${settingDraft.schemes.filter(sc=>(!sc.deleted_at||p?.scheme===sc.id)&&(!sc.mapping_placeholder||p?.scheme===sc.id)&&settingDraft.products.some(x=>x.scheme===sc.id)).map(sc=>option(sc.id,sc.crop+' / '+sc.segment+' / '+sc.packing_kg+' kg',group?.id)).join('')}</select></label><label>Product name<input id="product-name" value="${esc(p?.name||'')}"></label><label>Other ledger names (comma-separated)<input id="product-aliases" value="${esc(p?.aliases.join(', ')||'')}"></label></div><p>${p?'Crop, packing and group stay fixed to protect saved data.':'DAWAT 1 kg and DAWAT 3 kg are separate choices. New products join the selected group’s base scheme; select them in other saved schemes when needed.'}</p><button id="save-product" class="primary">Save Product</button>`);}
async function saveProduct(){const name=$('#product-name').value.trim(),aliases=$('#product-aliases').value.split(',').map(x=>x.trim()).filter(Boolean);if(!name)throw Error('Enter a product name.');const draft=structuredClone(settingDraft);const sc=draft.schemes.find(s=>s.id===$('#product-group').value);if(!sc)throw Error('Choose a crop / packing group.');const old=productEditing===null?null:draft.products[productEditing];if(draft.products.some(p=>p.id!==old?.id&&p.name.toLowerCase()===name.toLowerCase()&&p.crop===sc.crop&&p.segment===sc.segment&&Number(p.packing_kg)===Number(sc.packing_kg)))throw Error('This product already exists in this packing group. Use Edit Product.');if(old){const previousName=old.name;old.name=name;old.aliases=[...new Set([...aliases,...(previousName!==name?[previousName]:[])])];for(const scheme of draft.schemes)if(scheme.products.includes(old.id)&&scheme.cash?.products.includes(previousName))scheme.cash.products=scheme.cash.products.map(x=>x===previousName?name:x);}else{const id=uid();draft.products.push({id,name,aliases,crop:sc.crop,segment:sc.segment,segment_id:sc.segment_id,packing_kg:sc.packing_kg,scheme:sc.id});sc.products.push(id);}settingDraft=await api('/api/settings',draft);await refresh();$('#modal').close();settingsPage();toast('Product saved. Existing product and calculation identities are preserved.');}
function seasonField(i,k,l,v,t='text'){return `<label>${l}<input data-season="${i}" data-key="${k}" type="${t}" value="${esc(v)}"></label>`}
let builder,indexEditing,wizardStep=0,wizardErrors=[];
const wizardSteps=['Crop & Products','Choose Benefits','Rates & Slabs','Review & Save'];
function segmentTemplates(crop){let seen=new Set();return settingDraft.schemes.filter(s=>{let key=s.segment_id||s.segment;if(s.deleted_at||s.mapping_placeholder||s.crop!==crop||seen.has(key))return false;seen.add(key);return true})}
function useTemplate(id){let t=settingDraft.schemes.find(s=>s.id===id);if(!t)return;let oldId=builder?.id||uid();builder={...structuredClone(t),net_mode:t.net_mode||'price',net_cn_unit:t.net_cn_unit||t.unit,id:oldId,name:t.segment+' — New Scheme',season:record?.season||settingDraft.seasons[0]?.name||t.season,confirmed:false,remark:'Started from '+t.name};wizardErrors=[]}
function schemeBuilder(index){cashSettingsReturn=null;mappingSchemeProduct=null;indexEditing=index;wizardStep=0;wizardErrors=[];builder=index==null?null:structuredClone(settingDraft.schemes[index]);if(builder){builder.net_mode=builder.net_mode||'price';builder.net_cn_unit=builder.net_cn_unit||builder.unit;}if(index==null){const startingCrop=catalogCrops().includes(schemeCropFilter)?schemeCropFilter:catalogCrops()[0];const template=segmentTemplates(startingCrop)[0];if(!template){const pending=settingDraft.products.find(p=>p.crop===startingCrop);if(pending){createProductScheme(pending.id);return;}toast('Add a crop and packing group first under Products & Packing.');return;}useTemplate(template.id);};builderForm()}
function bs(k,label,choices){return `<label>${label}<select id="b-${k}" data-b-select="${k}">${choices.map(([v,l])=>option(v,l,builder[k])).join('')}</select></label>`}
function builderForm(){builder.net_mode=builder.net_mode||'price';builder.net_cn_unit=builder.net_cn_unit||builder.unit;const template=segmentTemplates(builder.crop).find(t=>(t.segment_id||t.segment)===(builder.segment_id||builder.segment));modal(`${pdfRateHintHTML()}<h2>${indexEditing==null?'Create New Scheme':'Edit Rates & Slabs'}</h2><div class="tabs">${wizardSteps.map((x,i)=>`<button data-wizard-step="${i}" class="${i===wizardStep?'active':''}">${i+1}. ${x}</button>`).join('')}</div>${wizardErrors.length?`<div class="warn"><strong>Please check</strong><ul>${wizardErrors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${wizardStep===0?`<div class="grid two"><label>Crop<select id="b-crop" ${indexEditing!==null?'disabled':''}>${catalogCrops().map(c=>option(c,c,builder.crop)).join('')}</select></label>${builder.record_product_scheme?bf('segment','Group / segment name'): `<label>Segment / packing group<select id="b-template" ${indexEditing!==null?'disabled':''}>${segmentTemplates(builder.crop).map(t=>option(t.id,t.segment+' · '+t.packing_kg+' kg packs',template?.id)).join('')}</select></label>`}${bf('name','Give this scheme a name')}<label>Season<select data-b-select="season">${settingDraft.seasons.map(x=>option(x.name,x.name,builder.season)).join('')}</select></label>${bf('states','Applicable states (comma-separated)',builder.states.join(', '))}${bs('unit','Calculate quantity in',[['kg','Kilograms (kg)'],['packet','Packets']])}</div><h3>Products covered</h3><p>Select products for this scheme/group. For corrected packing, edit the product mapping in Check Ledger first.</p>${settingDraft.products.filter(p=>p.crop===builder.crop&&(builder.record_product_scheme?Number(p.packing_kg)===Number(builder.packing_kg):(p.segment_id&&builder.segment_id?p.segment_id===builder.segment_id:p.segment===builder.segment))).map(p=>`<label class="check"><input type="checkbox" data-b-product="${p.id}" ${builder.products.includes(p.id)?'checked':''}>${esc(p.name+' · '+p.packing_kg+' kg pack')}</label>`).join('')}<p class="muted">${indexEditing===null?'This starts with the segment’s existing rates. Review them in step 3; it stays a draft until confirmed.':'Editing keeps the existing crop, segment and packing identity.'}</p>`:wizardStep===1?`<h3>Which benefits do you want?</h3><p>Tick the benefits to include. Unticking preserves the entered rates for later.</p><div class="grid two">${Object.entries(benefitNames).map(([k,l])=>`<label class="benefit-choice"><input type="checkbox" data-b-benefit="${k}" ${builder.benefits.includes(k)?'checked':''} ${k==='Net'?builder.benefits.some(x=>x!=='Net')?'disabled':'':builder.benefits.includes('Net')?'disabled':''}><span><strong>${l}</strong><small>${{Net:'Invoice-minus-net-price or a fixed CN amount per packet / kg.',ABS:'Token amount and incentive per kg or packet.',Quantity:'CN rate based on the quantity sold.',CD:'Discount by original payment date.',Extra:'Highest qualifying trip or extra CN.',Return:'Bonus when returns stay within the limit.'}[k]}</small></span></label>`).join('')}</div><p class="muted">Net Rate stands alone. Cash allocation remains separate from these benefits.</p>`:wizardStep===2?`<div class="card"><h3>Billing rate</h3><div class="grid two">${bf('billing','Invoice / reference rate ₹',null,'number')}${bs('billing_unit','Rate is per',[['kg','kg'],['packet','packet']])}</div><p class="muted">Actual invoice amounts and varying source rates remain in the ledger.</p></div>${builder.benefits.includes('Net')?`<div class="card"><h3>Net Rate</h3>${bs('net_mode','How to calculate this CN',[['price','Invoice minus net price (existing slabs)'],['fixed','Fixed CN per packet / kg']])}${builder.net_mode==='fixed'?`<div class="grid two">${bf('net_cn_rate','Dealer CN ₹ per unit',null,'number')}${bs('net_cn_unit','CN is per',[['packet','Packet'],['kg','kg']])}</div><p>Example: 100 net packets × ₹20 = ₹2,000 CN. Invoice money remains unchanged.</p>`:`<p>Each slab sets the net price per ${esc(builder.unit)} for the whole quantity.</p>${slabEditor('net')}`}</div>`:''}${builder.benefits.includes('ABS')?`<div class="card"><h3>Advance Booking (ABS)</h3><div class="grid">${bf('token','Token received ₹',null,'number')}${bf('abs_rate','ABS CN benefit ₹',null,'number')}${bs('abs_unit','Both rates are per',[['kg','kg'],['packet','packet']])}${bf('abs_start','Booking starts',null,'date')}${bf('abs_end','Booking ends',null,'date')}</div><details><summary>Allow an approved extension</summary>${bf('extended_end','Latest extended date',null,'date')}<p>A party approval and remark are still required for each extended allocation.</p></details></div>`:''}${builder.benefits.includes('Quantity')?`<div class="card"><h3>Quantity Discount</h3>${slabEditor('quantity')}<details><summary>How the slab rate applies</summary>${bs('quantity_mode','Quantity calculation',[['whole','Apply selected rate to the whole quantity'],['progressive','Apply each rate to its own quantity band']])}</details></div>`:''}${builder.benefits.includes('Extra')?`<div class="card"><h3>Trip / Extra Benefit</h3>${bs('extra_unit','Benefit amount means',[['fixed','One fixed rupee CN'],['kg','Rupees per kg sold'],['packet','Rupees per packet sold']])}${slabEditor('extra')}<p>Only the highest qualifying tier applies. Zero sales gives zero benefit.</p></div>`:''}${builder.benefits.includes('CD')?`<div class="card"><h3>Payment Discount (CD)</h3><p>Start and end dates are included. Add a 0% period where no discount applies.</p><table><tr><th>From date</th><th>Through date</th><th>Discount %</th><th></th></tr>${builder.cd.map((r,i)=>`<tr>${['start','end','percent'].map(k=>`<td><input type="${k==='percent'?'number':'date'}" data-b-row="cd,${i},${k}" value="${esc(r[k])}" aria-label="${k} period ${i+1}"></td>`).join('')}<td><button data-b-remove="cd,${i}">Remove</button></td></tr>`).join('')}</table><button data-b-add="cd">+ Add payment period</button><p class="muted">Original payment dates, pre-CD deductions and caps remain in force.</p></div>`:''}${builder.benefits.includes('Return')?`<div class="card"><h3>No / Low Return Bonus</h3><div class="grid">${bf('return_threshold','Returns allowed: maximum % of supply',null,'number')}${bf('return_rate','Bonus ₹ on net sold quantity',null,'number')}${bs('return_unit','Bonus is per',[['kg','kg'],['packet','packet']])}</div><p>0% means no returns. The maximum percentage is included.</p></div>`:''}`:schemeReview()}<div class="actions"><button id="wizard-back" ${wizardStep===0?'disabled':''}>Back</button>${wizardStep<3?'<button id="wizard-next" class="primary">Next</button>':'<button id="commit-scheme" class="primary">Save Scheme</button>'}<button id="save-incomplete-scheme">Save as Draft</button></div><p class="muted">No technical IDs or formulas to enter. Existing finalised calculations retain their original settings.</p>`)}
function schemeReview(){return `<h3>${esc(builder.name)}</h3><p>${esc(builder.crop+' / '+builder.segment)} · ${esc(builder.season)} · ${esc(builder.unit)}</p><p>States: ${esc(builder.states.join(', ')||'Not entered')}</p><p>Products: ${builder.products.map(id=>esc(settingDraft.products.find(p=>p.id===id)?.name||'Unknown')).join(', ')}</p>${Object.entries(benefitNames).filter(([k])=>builder.benefits.includes(k)).map(([k,l])=>`<div class="card"><h3>${l}</h3>${k==='ABS'?`Token ${schemeMoney(builder.token)} / ${esc(builder.abs_unit)}; benefit ${schemeMoney(builder.abs_rate)} / ${esc(builder.abs_unit)}<p>${schemeDate(builder.abs_start)} through ${schemeDate(builder.abs_end)}</p>`:k==='Return'?`Maximum returns ${esc(builder.return_threshold)}%; bonus ${schemeMoney(builder.return_rate)} / ${esc(builder.return_unit)} on net sold quantity`:k==='Net'&&builder.net_mode==='fixed'?`Fixed dealer CN ${schemeMoney(builder.net_cn_rate)} per ${esc(builder.net_cn_unit)} on net sold quantity`:k==='CD'?`<table><tr><th>From</th><th>Through</th><th>%</th></tr>${builder.cd.map(r=>`<tr><td>${schemeDate(r.start)}</td><td>${schemeDate(r.end)}</td><td>${esc(r.percent)}</td></tr>`).join('')}</table>`:`<table><tr><th>Quantity</th><th>${k==='Net'?'Net price':k==='Extra'?'CN worth':'CN rate'}</th></tr>${builder[{Net:'net',Quantity:'quantity',Extra:'extra'}[k]].map(r=>`<tr><td>${r.inclusive?'From':'Above'} ${esc(r.above)} ${r.upto?'through '+esc(r.upto):'and above'} ${esc(builder.unit)} ${esc(r.name)}</td><td>${schemeMoney(r.rate)} ${k==='Extra'?builder.extra_unit==='fixed'?'total':'/ '+esc(builder.extra_unit):'/ '+esc(builder.unit)}</td></tr>`).join('')}</table>`}</div>`).join('')}${bf('remark','Reason / note for this scheme')}<label class="check"><input type="checkbox" id="b-confirmed" ${builder.confirmed?'checked':''}>I checked the states, dates, products and rates; this setup is ready for use</label><details><summary>Credit note narration</summary>${bf('narration','CN description template')}<p>Keep {party}, {crop}, {segment}, {season} and {benefit} to identify each separate CN.</p></details>`}
function bf(k,l,v=null,t='text'){return `<label>${l}<input id="b-${k}" data-b-key="${k}" type="${t}" ${t==='number'?'step="any" min="0"':''} value="${esc(v??builder[k])}"></label>`}
function slabEditor(k){let inclusive=k==='extra'&&builder[k].some(r=>r.inclusive);return `<p>Quantity is in ${esc(builder.unit)}. ${inclusive?'Minimum quantities are included.':'Upper limits are included.'} The highest rate continues above the last slab.</p><table><tr><th>${inclusive?'Minimum quantity':'Above quantity'}</th>${inclusive?'':'<th>Up to quantity</th>'}<th>${k==='net'?'Net price ₹':k==='extra'?'Benefit CN worth ₹':'CN ₹ / '+esc(builder.unit)}</th>${k==='extra'?'<th>Benefit name</th>':''}<th></th></tr>${builder[k].map((r,i)=>`<tr>${(inclusive?['above','rate','name']:k==='extra'?['above','upto','rate','name']:['above','upto','rate']).map(f=>`<td><input data-b-row="${k},${i},${f}" type="${f==='name'?'text':'number'}" ${f!=='name'?'step="any" min="0"':''} value="${esc(r[f])}" aria-label="${f} slab ${i+1}"></td>`).join('')}<td><button data-b-remove="${k},${i}">Remove</button></td></tr>`).join('')}</table><button data-b-add="${k}">+ Add slab</button>`}
